export const LABOR_MANAGEMENT_TABS = [
  { id: "home", label: "Roster" },
  { id: "attendance", label: "Attendance" },
  { id: "performance-reviews", label: "Compliance" },
  { id: "training", label: "Training" },
  { id: "interviews", label: "Interviews" },
  { id: "hour-analysis", label: "Capacity Planning" },
];

const TABS = LABOR_MANAGEMENT_TABS;

const LABOR_TAB_IDS = new Set([...TABS, ...HIDDEN_LABOR_TABS].map((tab) => tab.id));
const normalizeLaborTab = (value) => value === "labor-model" ? "hour-analysis" : (LABOR_TAB_IDS.has(value) ? value : "home");
export const COMPLIANCE_VIEW_OPTIONS = [
  { id: "employees", label: "Employees" },
  { id: "summary", label: "Summary" },
  { id: "requirements", label: "Requirements" },
  { id: "history", label: "History" },
];
const COMPLIANCE_VIEW_IDS = new Set(COMPLIANCE_VIEW_OPTIONS.map((view) => view.id));
const normalizeComplianceView = (value) => COMPLIANCE_VIEW_IDS.has(value) ? value : "employees";

export function buildLaborModulePanelKey({ tab, interviewView, attendanceView, capacityPlanningView, complianceView } = {}) {
  const normalizedTab = normalizeLaborTab(tab);
  const parts = [
    normalizedTab,
    normalizedTab === "interviews" ? normalizeInterviewView(interviewView) : "",
    normalizedTab === "attendance" ? normalizeAttendanceView(attendanceView) : "",
    normalizedTab === "hour-analysis" ? normalizeCapacityPlanningView(capacityPlanningView) : "",
  ];
  if (normalizedTab === "performance-reviews") parts.push(normalizeComplianceView(complianceView));
  return parts.join(":");
}

function LaborViewSwitcher({ options = [], value, onChange, variant }) {
  const visibleOptions = options.filter(Boolean);
  const activeIndex = Math.max(0, visibleOptions.findIndex((option) => option.id === value));
  const hasSubtitles = visibleOptions.some((option) => option.subtitle);
  if (!visibleOptions.length) return null;
  if (variant === "tabs") {
    return (
      <div className="labor-view-tabs" role="tablist">
        {visibleOptions.map((option) => {
          const active = option.id === value;
          return (
            <button
              key={option.id}
              type="button"
              role="tab"
              aria-selected={active}
              className={`labor-view-tab${active ? " is-active" : ""}`}
              onClick={() => onChange(option.id)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    );
  }
  return (
    <div
      className={`labor-view-switcher${hasSubtitles ? "" : " is-compact"}`}
      style={{
        "--labor-view-count": visibleOptions.length,
        "--labor-view-active-index": activeIndex,
      }}
    >
      <div className="labor-view-switcher-indicator" aria-hidden="true" />
      {visibleOptions.map((option) => {
        const active = option.id === value;
        return (
          <button
            key={option.id}
            type="button"
            className={`labor-view-option${active ? " is-active" : ""}`}
            onClick={() => onChange(option.id)}
          >
            <span>{option.label}</span>
            {option.subtitle ? <small>{option.subtitle}</small> : null}
          </button>
        );
      })}
    </div>
  );
}


function LaborCapacityModelControl({
  models = [],
  activeModel = null,
  editingModel = null,
  canEdit = false,
  available = true,
  saving = false,
  actionId = "",
  creating = false,
  onSelect,
  onRename,
  onCreate,
  onDuplicate,
  onActivate,
  onArchive,
}) {
  const [open, setOpen] = useState(false);
  const modelRows = normalizeLaborCapacityModels(models).filter((model) => !model.archived_at);
  const selectedModel = editingModel || activeModel || modelRows[0] || null;
  const isActive = Boolean(selectedModel?.id && activeModel?.id === selectedModel.id);
  const lastSaved = selectedModel?.updated_at ? formatTrainingTimestamp(selectedModel.updated_at) : "Not saved yet";
  const actor = selectedModel?.updated_by_name || selectedModel?.created_by_name || "Staff";
  const statusTone = selectedModel?.archived_at ? "archived" : isActive ? "active" : "inactive";
  const statusLabel = statusTone === "archived" ? "Archived" : statusTone === "active" ? "Active" : "Not in use";
  const busy = saving || Boolean(actionId) || creating;

  if (!available) {
    return (
      <div className="labor-capacity-model-control is-unavailable">
        <div className="labor-capacity-model-object">
          <div className="labor-capacity-model-object-icon"><I.Layers /></div>
          <div>
            <span>Legacy labor_hour_analysis settings</span>
            <strong>Saved model table is not available yet</strong>
            <small>Staffing Capacity is using the legacy settings row.</small>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="labor-capacity-model-control">
      <div className="labor-capacity-model-object">
        <div className="labor-capacity-model-object-icon"><I.Layers /></div>
        <div>
          <span>Labor Model</span>
          <strong>{selectedModel?.name || "No saved model"}</strong>
          <small>
            <em className={`labor-capacity-model-state is-${statusTone}`}>{statusLabel}</em>
            {isActive ? "Feeds Staffing Capacity" : "Does not affect Staffing Capacity until activated"}
          </small>
        </div>
      </div>
      <div className="labor-capacity-model-meta">
        <div>
          <span>Active</span>
          <strong>{activeModel?.name || "None"}</strong>
        </div>
        <div>
          <span>Last saved</span>
          <strong>{saving ? "Saving..." : lastSaved}</strong>
          <small>{actor}</small>
        </div>
      </div>
      <div className="labor-capacity-model-actions-v2">
        <div className="labor-capacity-model-picker">
          <button
            type="button"
            className="labor-capacity-model-picker-trigger"
            disabled={!canEdit || modelRows.length === 0}
            onClick={() => setOpen((prev) => !prev)}
          >
            <span>{selectedModel?.name || "Choose model"}</span>
            <I.ChevronDown />
          </button>
          {open && (
            <div className="labor-capacity-model-picker-menu">
              {modelRows.map((model) => {
                const modelIsActive = activeModel?.id === model.id;
                return (
                  <button
                    key={model.id}
                    type="button"
                    className={`labor-capacity-model-picker-row${selectedModel?.id === model.id ? " is-selected" : ""}`}
                    onClick={() => {
                      onSelect?.(model.id);
                      setOpen(false);
                    }}
                  >
                    <span>
                      <strong>{model.name}</strong>
                      <small>{model.updated_at ? formatTrainingTimestamp(model.updated_at) : "No saved timestamp"} by {model.updated_by_name || model.created_by_name || "Staff"}</small>
                    </span>
                    <em className={`labor-capacity-model-state is-${modelIsActive ? "active" : "inactive"}`}>{modelIsActive ? "Active" : "Not in use"}</em>
                  </button>
                );
              })}
              {modelRows.length === 0 && <div className="labor-capacity-model-picker-empty">No saved Labor Models yet.</div>}
            </div>
          )}
        </div>
        {canEdit && (
          <div className="labor-capacity-model-command-row">
            <button type="button" onClick={onRename} disabled={!selectedModel || busy}><I.Pencil /> Rename</button>
            <button type="button" onClick={onCreate} disabled={creating || busy}><I.Plus /> New Model</button>
            <button type="button" onClick={onDuplicate} disabled={!selectedModel || busy}><I.Layers /> Duplicate</button>
            <button type="button" className="is-primary" onClick={onActivate} disabled={!selectedModel || isActive || busy}><I.Check /> Activate</button>
            <button type="button" className="is-danger" onClick={onArchive} disabled={!selectedModel || isActive || busy}><I.Trash /> Archive</button>
          </div>
        )}
      </div>
    </div>
  );
}

const SORT_DIRECTION_LABELS = {
  asc: "Ascending",
  desc: "Descending",
};

function getLaborSortDisplayLabel(sort = {}, columns = [], defaultSort = {}) {
  const column = columns.find((item) => item.key === sort.key);
  if (!column) return "Sort";
  if (sort.key === defaultSort.key && sort.direction === defaultSort.direction) return `Sort: ${column.label}`;
  return `Sort: ${column.label} ${SORT_DIRECTION_LABELS[sort.direction] || "Ascending"}`;
}

function LaborSortControl({ sort, columns = [], defaultSort, onChange }) {
  const [open, setOpen] = useState(false);
  const [ready, setReady] = useState(false);
  const pickerRef = useRef(null);
  const activeSort = sort || defaultSort || {};
  const normalizedDefault = defaultSort || columns[0] || { key: "", direction: "asc" };
  const isDefault = activeSort.key === normalizedDefault.key && activeSort.direction === normalizedDefault.direction;

  useEffect(() => {
    if (!open) {
      setReady(false);
      return undefined;
    }
    const timer = window.setTimeout(() => setReady(true), 10);
    return () => window.clearTimeout(timer);
  }, [open]);

  useEffect(() => {
    if (!open || typeof document === "undefined") return undefined;
    const handlePointerDown = (event) => {
      if (!pickerRef.current || pickerRef.current.contains(event.target)) return;
      setOpen(false);
    };
    const handleKeyDown = (event) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open]);

  return (
    <div className="labor-sort-control" ref={pickerRef}>
      <button
        type="button"
        className={`labor-sort-trigger${open ? " is-open" : ""}${!isDefault ? " is-active" : ""}`}
        onClick={() => setOpen((prev) => !prev)}
      >
        <I.SortNone />
        <span>{getLaborSortDisplayLabel(activeSort, columns, normalizedDefault)}</span>
        <span style={{ display: "flex", transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform 160ms ease" }}>
          <I.ChevronDown />
        </span>
      </button>
      {open && (
        <div className="labor-sort-panel">
          <div className="hour-analysis-picker-heading">Sort Table</div>
          <div className="labor-sort-panel-body">
            <button
              type="button"
              className={`hour-analysis-picker-option${isDefault ? " is-active" : ""} is-reset`}
              style={{ animation: ready ? "filterChipIn 0.22s ease-out both" : "none" }}
              onClick={() => {
                onChange?.(normalizedDefault);
                setOpen(false);
              }}
            >
              Reset to position order
            </button>
            <div className="labor-sort-option-grid">
              {columns.map((column, index) => (
                <div
                  key={column.key}
                  className="labor-sort-option-row"
                  style={{ animation: ready ? `filterChipIn 0.24s ease-out ${(index + 1) * 0.035}s both` : "none" }}
                >
                  <span>{column.label}</span>
                  <div>
                    {["asc", "desc"].map((direction) => {
                      const active = activeSort.key === column.key && activeSort.direction === direction;
                      return (
                        <button
                          key={direction}
                          type="button"
                          className={`labor-sort-direction${active ? " is-active" : ""}`}
                          onClick={() => {
                            onChange?.({ key: column.key, direction });
                            setOpen(false);
                          }}
                        >
                          {SORT_DIRECTION_LABELS[direction]}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

