function getReviewCycleEvidenceDocument(reviewCycle = {}, documentsById = {}) {
  const evidence = getCompletionEvidence(reviewCycle);
  const policyCell = getReviewCyclePolicyCell(reviewCycle);
  const documentIdCandidates = [
    evidence.documentId,
    evidence.id,
    policyCell.labor_employee_document_id,
    policyCell.document_id,
    policyCell.evidence_document_id,
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const matchedDocument = documentIdCandidates.map((id) => documentsById[id]).find(Boolean);
  if (matchedDocument) return matchedDocument;

  const fileName = evidence.fileName || policyCell.evidence_label || policyCell.document_file_name || "";
  const storagePath = evidence.storagePath || policyCell.storage_path || "";
  const externalUrl = evidence.url || policyCell.external_evidence_url || "";
  if (!fileName && !storagePath && !externalUrl) return null;

  return {
    id: documentIdCandidates[0] || `${fileName || storagePath || externalUrl}-compliance-evidence`,
    document_type: "performance_review_evidence",
    file_name: fileName || "Compliance evidence PDF",
    storage_bucket: evidence.storageBucket || policyCell.storage_bucket || LABOR_EMPLOYEE_ATTACHMENT_BUCKET,
    storage_path: storagePath,
    external_url: externalUrl,
    mime_type: "application/pdf",
    file_size_bytes: Number(policyCell.file_size_bytes || 0),
    uploaded_at: evidence.uploadedAt || policyCell.uploaded_at || "",
    uploaded_by_name: evidence.uploadedByName || policyCell.uploaded_by_name || "",
    metadata: {
      source_module: "compliance_requirements",
      source: "compliance_grid",
    },
  };
}
function AttachmentPdfPreview({ url, fileName }) {
  const objectUrlRef = useRef("");
  const [previewState, setPreviewState] = useState({ loading: false, error: "", objectUrl: "" });

  useEffect(() => {
    if (!url) return undefined;
    let cancelled = false;
    if (objectUrlRef.current) {
      URL.revokeObjectURL(objectUrlRef.current);
      objectUrlRef.current = "";
    }
    setPreviewState({ loading: true, error: "", objectUrl: "" });

    async function loadPdfBlob() {
      try {
        const response = await fetch(url, { cache: "no-store" });
        if (!response.ok) throw new Error("Unable to load PDF evidence file.");
        const blob = await response.blob();
        const pdfBlob = blob.type === "application/pdf" ? blob : new Blob([blob], { type: "application/pdf" });
        const objectUrl = URL.createObjectURL(pdfBlob);
        if (cancelled) URL.revokeObjectURL(objectUrl);
        else {
          objectUrlRef.current = objectUrl;
          setPreviewState({ loading: false, error: "", objectUrl });
        }
      } catch (error) {
        if (!cancelled) {
          setPreviewState({ loading: false, error: error?.message || "Unable to load PDF preview.", objectUrl: "" });
        }
      }
    }

    loadPdfBlob();
    return () => {
      cancelled = true;
      if (objectUrlRef.current) {
        URL.revokeObjectURL(objectUrlRef.current);
        objectUrlRef.current = "";
      }
    };
  }, [url]);

  const openOriginal = useCallback(() => {
    if (url) window.open(url, "_blank", "noopener,noreferrer");
  }, [url]);

  return (
    <div style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden", background: "#fff" }}>
      {previewState.error ? (
        <div style={{ minHeight: 420, display: "grid", placeItems: "center", gap: 12, padding: 24, textAlign: "center" }}>
          <div>
            <div style={{ fontSize: 14, fontWeight: 950, color: C.text }}>PDF preview could not render here.</div>
            <div style={{ marginTop: 5, fontSize: 12, fontWeight: 750, color: C.textMut }}>{fileName || "Compliance evidence PDF"}</div>
          </div>
          <Btn variant="secondary" size="sm" icon={<I.FileText />} onClick={openOriginal}>Open Original PDF</Btn>
        </div>
      ) : previewState.objectUrl ? (
        <iframe
          title={fileName || "Compliance evidence PDF"}
          src={`${previewState.objectUrl}#toolbar=1&navpanes=0&view=FitH`}
          style={{ width: "100%", height: "100%", border: "none", background: "#fff" }}
        />
      ) : (
        <div style={{ minHeight: 420, height: "100%", display: "grid", placeItems: "center", color: C.textMut, fontSize: 13, fontWeight: 850 }}>
          Loading PDF preview...
        </div>
      )}
      {previewState.loading && (
        <div style={{ position: "absolute", right: 14, top: 14, zIndex: 4, borderRadius: 999, background: "rgba(255,255,255,0.95)", border: `1px solid ${C.borderLight}`, color: C.textSec, fontSize: 11, fontWeight: 900, padding: "5px 9px", boxShadow: "0 8px 20px rgba(15,23,42,0.12)" }}>
          Loading
        </div>
      )}
    </div>
  );
}






