export function isDefaultReviewComplianceRequirement(row = {}) {
  if (!isObjectRow(row) || row.is_active === false) return false;
  const metadata = isObjectRow(row.metadata) ? row.metadata : {};
  return String(row.requirement_kind || "") === "review_checkpoint"
    && !isCustomComplianceRequirement(row)
    && (
      String(row.display_group || "") === "reviews"
      || metadata.legacy_review_cycle
      || String(row.slug || "").startsWith("review_")
    );
}







































function getLaborModelRolePalette(groupKey = "", roleColors = null) {
  const normalizedGroup = normalizeLaborModelGroupKey(groupKey);
  const normalizedColors = isObjectRow(roleColors) ? normalizeLaborModelRolePalette(roleColors) : null;
  return normalizedColors?.[normalizedGroup] || LABOR_MODEL_ROLE_PALETTE[normalizedGroup] || LABOR_MODEL_ROLE_PALETTE.other;
}

function getLaborModelCoverageRoleStyle(groupKey = "", roleColors = null) {
  const palette = getLaborModelRolePalette(groupKey, roleColors);
  return {
    "--labor-model-cell-strong": palette.strong,
    "--labor-model-cell-accent": palette.accent,
    "--labor-model-cell-soft": palette.soft,
    "--labor-model-cell-text": palette.text,
  };
}













export function getLaborModelDefaultCoverageValueForRow(rowGroupKey = "") {
  return buildLaborModelCoverageValue({ duration: "full", rowGroupKey });
}

export function setLaborModelCoverageDuration(value = "", rowGroupKey = "", duration = "full") {
  const normalized = normalizeLaborModelCoverageCell(value);
  if (!normalized) return buildLaborModelCoverageValue({ duration, rowGroupKey });
  if (normalized === LABOR_MODEL_MARKETING_COVERAGE_VALUE) return normalized;
  const roleOption = getLaborModelCoverageRoleOptionForCell(normalized, rowGroupKey);
  return buildLaborModelCoverageValue({ duration, roleValue: roleOption?.label, rowGroupKey });
}

export function setLaborModelCoveragePosition(value = "", rowGroupKey = "", positionValue = "") {
  const normalizedPosition = normalizeLaborModelCoverageCell(positionValue);
  if (!normalizedPosition) return "";
  if (normalizedPosition === LABOR_MODEL_MARKETING_COVERAGE_VALUE) return LABOR_MODEL_MARKETING_COVERAGE_VALUE;
  const duration = getLaborModelCoverageDuration(value) || "full";
  const roleOption = getLaborModelCoverageExplicitRoleOption(normalizedPosition) || getLaborModelCoverageRoleOption(normalizedPosition);
  return buildLaborModelCoverageValue({ duration, roleValue: roleOption?.label, rowGroupKey });
}

function getLaborModelNextCoverageValue(value = "", rowGroupKey = "") {
  const kind = getLaborModelCoverageKind(value);
  if (kind === "empty") return getLaborModelDefaultCoverageValueForRow(rowGroupKey);
  return "";
}


export function getLaborModelCoverageDisplay(value = "", rowGroupKey = "") {
  const normalized = normalizeLaborModelCoverageCell(value);
  const roleOption = getLaborModelCoverageRoleOptionForCell(normalized, rowGroupKey);
  if (normalized === LABOR_MODEL_FULL_COVERAGE_VALUE) return roleOption?.label || "";
  if (normalized === LABOR_MODEL_HALF_COVERAGE_VALUE) return roleOption?.label || "1/2";
  if (normalized.startsWith(`${LABOR_MODEL_HALF_COVERAGE_VALUE}:`)) {
    return roleOption?.label || "1/2";
  }
  if (roleOption) return roleOption.label;
  return normalized;
}




















function cloneDefaultHourAnalysisLaborModel() {
  return JSON.parse(JSON.stringify(DEFAULT_HOUR_ANALYSIS_LABOR_MODEL));
}




function normalizeHourAnalysisLaborModel(value = {}) {
  const defaults = cloneDefaultHourAnalysisLaborModel();
  const source = isObjectRow(value) ? value : {};
  const rawDays = isObjectRow(source.days) ? source.days : source;
  return {
    version: Number(source.version || defaults.version || 1),
    source: String(source.source || defaults.source || "").trim(),
    breakers: normalizeLaborModelBreakerSettings(source.breakers || source.greyBars || source.grayBars || source.breakerSettings || source.breaker_settings),
    days: Object.fromEntries(LABOR_MODEL_DAY_KEYS.map((dayKey) => [
      dayKey,
      normalizeHourAnalysisLaborModelDay(dayKey, rawDays[dayKey], defaults.days[dayKey]),
    ])),
  };
}

export function removeLaborModelColumnFromDay(day = {}, columnIndex = 0, dayKey = "day") {
  const normalizedDay = normalizeHourAnalysisLaborModelDay(dayKey, day, day);
  const targetIndex = Number(columnIndex);
  if (!Number.isInteger(targetIndex) || targetIndex < 0 || targetIndex >= normalizedDay.columns.length) {
    return { day: normalizedDay, removedColumn: null, error: "Choose a valid time slot." };
  }
  if (normalizedDay.columns.length <= 1) {
    return { day: normalizedDay, removedColumn: null, error: "At least one time slot is required." };
  }
  const removedColumn = normalizedDay.columns[targetIndex];
  const mergeIndex = targetIndex > 0 ? targetIndex - 1 : 1;
  const targetRange = parseLaborModelTimeRange(removedColumn.label);
  const mergeColumn = normalizedDay.columns[mergeIndex];
  const mergeRange = parseLaborModelTimeRange(mergeColumn?.label);
  let nextColumns = normalizedDay.columns.map((column) => ({ ...column }));
  let mergedColumn = null;

  if (targetRange.valid && mergeRange.valid && mergeColumn) {
    const mergedStart = mergeIndex < targetIndex ? mergeRange.start : targetRange.start;
    const mergedEnd = mergeIndex < targetIndex ? targetRange.end : mergeRange.end;
    const mergedLabel = formatLaborModelTimeRange(mergedStart, mergedEnd);
    mergedColumn = normalizeHourAnalysisLaborModelColumn({
      ...mergeColumn,
      label: mergedLabel,
    }, mergeIndex, dayKey);
    nextColumns[mergeIndex] = mergedColumn;
  }

  nextColumns = nextColumns.filter((_, index) => index !== targetIndex);
  const validation = validateLaborModelColumns(nextColumns);
  if (!validation.valid) {
    return {
      day: normalizedDay,
      removedColumn: null,
      error: validation.errors[0]?.message || "Time slots must stay contiguous.",
    };
  }

  const nextRows = normalizedDay.rows.map((row) => {
    const coverage = [...row.coverage];
    if (mergedColumn) {
      const existingValue = String(coverage[mergeIndex] || "").trim();
      const removedValue = String(coverage[targetIndex] || "").trim();
      coverage[mergeIndex] = existingValue || removedValue;
    }
    return {
      ...row,
      coverage: coverage.filter((_, index) => index !== targetIndex),
    };
  });

  return {
    day: {
      ...normalizedDay,
      columns: nextColumns,
      rows: nextRows,
    },
    removedColumn,
    mergedColumn,
    error: "",
  };
}


function calculateLaborModelRowHours(row = {}, columns = []) {
  return calculateLaborModelRowHourBuckets(row, columns).operatingHours;
}


function buildHourAnalysisLaborModelSummary(model = DEFAULT_HOUR_ANALYSIS_LABOR_MODEL) {
  const normalizedModel = normalizeHourAnalysisLaborModel(model);
  const roleWeekly = makeLaborModelRoleHoursBucket();
  const dayRows = LABOR_MODEL_DAY_KEYS.map((dayKey) => {
    const day = normalizedModel.days[dayKey];
    const columnValidation = validateLaborModelColumns(day.columns);
    const roleHours = makeLaborModelRoleHoursBucket();
    let totalHours = 0;
    let marketingHours = 0;
    let peakCoverage = 0;
    const baseRowSummaries = day.rows.map((row) => {
      const rowBuckets = calculateLaborModelRowHourBuckets(row, day.columns);
      const rowHours = rowBuckets.operatingHours;
      const groupKey = normalizeLaborModelGroupKey(row.group_key, row);
      Object.entries(rowBuckets.roleHours || {}).forEach(([roleKey, roleHourValue]) => {
        if (!HOUR_ANALYSIS_GROUP_LABELS[roleKey] || roleHourValue <= 0) return;
        roleHours[roleKey] = normalizeHourAnalysisDelta((roleHours[roleKey] || 0) + roleHourValue);
        roleWeekly[roleKey] = normalizeHourAnalysisDelta((roleWeekly[roleKey] || 0) + roleHourValue);
      });
      totalHours = normalizeHourAnalysisDelta(totalHours + rowHours);
      marketingHours = normalizeHourAnalysisDelta(marketingHours + rowBuckets.marketingHours);
      return {
        ...row,
        group_key: groupKey,
        hours: rowHours,
        roleHours: rowBuckets.roleHours,
        marketingHours: rowBuckets.marketingHours,
        totalHours: rowBuckets.totalHours,
        breakHours: rowBuckets.breakHours,
      };
    });
    const rowSummaries = baseRowSummaries.map((row, index, rows) => {
      const runKey = `${row.group_key}:${row.shift_type}`;
      let startIndex = index;
      while (startIndex > 0 && `${rows[startIndex - 1].group_key}:${rows[startIndex - 1].shift_type}` === runKey) startIndex -= 1;
      let endIndex = index;
      while (endIndex + 1 < rows.length && `${rows[endIndex + 1].group_key}:${rows[endIndex + 1].shift_type}` === runKey) endIndex += 1;
      const runLength = endIndex - startIndex + 1;
      return {
        ...row,
        runIndex: index - startIndex + 1,
        runLength,
      };
    });
    const columnTotals = day.columns.map((column, index) => {
      const operatingCoverage = rowSummaries.reduce((sum, row) => sum + getLaborModelCoverageOperatingWeight(row.coverage[index]), 0);
      const marketingCoverage = rowSummaries.reduce((sum, row) => sum + getLaborModelCoverageMarketingWeight(row.coverage[index]), 0);
      const slotHours = normalizeHourAnalysisNumber(column.hours, 0);
      peakCoverage = Math.max(peakCoverage, operatingCoverage);
      return {
        index,
        label: column.label,
        operatingCoverage: normalizeHourAnalysisNumber(operatingCoverage, 0),
        marketingCoverage: normalizeHourAnalysisNumber(marketingCoverage, 0),
        operatingHours: normalizeHourAnalysisNumber(operatingCoverage * slotHours, 0),
        marketingHours: normalizeHourAnalysisNumber(marketingCoverage * slotHours, 0),
      };
    });
    return {
      key: dayKey,
      label: LABOR_MODEL_DAY_LABELS[dayKey] || dayKey,
      shortLabel: LABOR_MODEL_DAY_SHORT_LABELS[dayKey] || dayKey,
      coverageWindow: day.coverage_window,
      columns: day.columns,
      rows: rowSummaries,
      roleHours,
      totalHours,
      marketingHours,
      columnTotals,
      peakCoverage,
      columnValidation,
    };
  });
  const totalWeekly = normalizeHourAnalysisNumber(dayRows.reduce((sum, row) => sum + row.totalHours, 0), 0);
  const totalMarketingWeekly = normalizeHourAnalysisNumber(dayRows.reduce((sum, row) => sum + row.marketingHours, 0), 0);
  const highestDay = dayRows.reduce((winner, row) => (row.totalHours > (winner?.totalHours || 0) ? row : winner), dayRows[0] || null);
  return {
    model: normalizedModel,
    dayRows,
    roleWeekly: Object.fromEntries(Object.entries(roleWeekly).map(([key, value]) => [key, normalizeHourAnalysisNumber(value, 0)])),
    totalWeekly,
    totalMarketingWeekly,
    averageDaily: normalizeHourAnalysisNumber(totalWeekly / 7, 0),
    highestDay,
    hasRows: dayRows.some((day) => day.rows.length > 0 && day.columns.length > 0),
  };
}

export function buildLaborModelCrossRoleCoverageSummary(settings = {}) {
  const normalizedSettings = normalizeHourAnalysisSettings(settings);
  const rows = [];
  LABOR_MODEL_DAY_KEYS.forEach((dayKey) => {
    const day = normalizedSettings.laborModel.days[dayKey];
    if (!day) return;
    day.rows.forEach((row) => {
      const homeGroupKey = normalizeLaborModelGroupKey(row.group_key, row);
      const rawOperatingHours = row.coverage.reduce((sum, cell, index) => {
        const weight = getLaborModelCoverageOperatingWeight(cell);
        return sum + (weight * normalizeHourAnalysisNumber(day.columns[index]?.hours, 0));
      }, 0);
      const rowBuckets = calculateLaborModelRowHourBuckets(row, day.columns);
      const operatingScale = rawOperatingHours > 0 ? rowBuckets.operatingHours / rawOperatingHours : 0;
      row.coverage.forEach((cell, index) => {
        const workedGroupKey = getLaborModelCoverageOperatingGroupKey(cell, row);
        const weight = getLaborModelCoverageOperatingWeight(cell);
        if (!homeGroupKey || !workedGroupKey || homeGroupKey === workedGroupKey || weight <= 0) return;
        const hours = normalizeHourAnalysisNumber(weight * normalizeHourAnalysisNumber(day.columns[index]?.hours, 0) * operatingScale, 0);
        if (hours <= 0) return;
        const key = `${homeGroupKey}->${workedGroupKey}`;
        const existing = rows.find((item) => item.key === key);
        if (existing) {
          existing.hours = normalizeHourAnalysisNumber(existing.hours + hours, 0);
          existing.slots += 1;
          if (!existing.days.includes(dayKey)) existing.days.push(dayKey);
          return;
        }
        rows.push({
          key,
          from_group_key: homeGroupKey,
          from_label: getHourAnalysisGroupShortLabel(homeGroupKey),
          to_group_key: workedGroupKey,
          to_label: getHourAnalysisGroupShortLabel(workedGroupKey),
          hours,
          slots: 1,
          days: [dayKey],
        });
      });
    });
  });
  return rows
    .sort((left, right) => (right.hours - left.hours) || left.key.localeCompare(right.key))
    .map((row) => ({
      ...row,
      day_labels: row.days.map((dayKey) => LABOR_MODEL_DAY_SHORT_LABELS[dayKey] || dayKey),
    }));
}


export function normalizeLaborCapacityModelVersionRow(row = {}) {
  const source = isObjectRow(row) ? row : {};
  const createdAt = source.created_at || source.createdAt || null;
  return {
    id: String(source.id || makeLaborCapacityModelTempId("labor-model-version")).trim(),
    model_id: String(source.model_id || source.modelId || "").trim(),
    location_id: String(source.location_id || source.locationId || "").trim(),
    version_no: Math.max(0, Math.round(Number(source.version_no ?? source.versionNo ?? 0) || 0)),
    model_name: normalizeLaborCapacityModelName(source.model_name || source.modelName || source.name, LABOR_CAPACITY_MODEL_DEFAULT_NAME),
    model_settings_snapshot: normalizeHourAnalysisSettings(source.model_settings_snapshot || source.modelSettingsSnapshot || source.settings || source.model_settings),
    change_type: String(source.change_type || source.changeType || "update").trim() || "update",
    change_summary: String(source.change_summary || source.changeSummary || "").trim(),
    changed_by_user_id: source.changed_by_user_id || source.changedByUserId || null,
    changed_by_name: String(source.changed_by_name || source.changedByName || "").trim(),
    created_at: createdAt,
  };
}

export function normalizeLaborCapacityModelVersions(rows = []) {
  return toObjectRows(rows)
    .map((row) => normalizeLaborCapacityModelVersionRow(row))
    .sort((left, right) => {
      if (right.version_no !== left.version_no) return right.version_no - left.version_no;
      return String(right.created_at || "").localeCompare(String(left.created_at || ""));
    });
}

export function summarizeLaborCapacityModelSnapshotDiff(currentSettings = {}, snapshotSettings = {}) {
  const current = normalizeHourAnalysisSettings(currentSettings);
  const snapshot = normalizeHourAnalysisSettings(snapshotSettings);
  const currentSummary = buildHourAnalysisLaborModelSummary(current.laborModel);
  const snapshotSummary = buildHourAnalysisLaborModelSummary(snapshot.laborModel);
  const changes = [];
  const pushHoursDiff = (label, before, after) => {
    const normalizedBefore = normalizeHourAnalysisNumber(before, 0);
    const normalizedAfter = normalizeHourAnalysisNumber(after, 0);
    if (normalizedBefore === normalizedAfter) return;
    const delta = normalizeHourAnalysisDelta(normalizedAfter - normalizedBefore);
    changes.push(`${label}: ${formatHourAnalysisHours(normalizedBefore)} -> ${formatHourAnalysisHours(normalizedAfter)} hrs (${delta > 0 ? "+" : "-"}${formatHourAnalysisHours(Math.abs(delta))})`);
  };

  pushHoursDiff("Weekly floor", snapshotSummary.totalWeekly, currentSummary.totalWeekly);
  pushHoursDiff("Marketing", snapshotSummary.totalMarketingWeekly, currentSummary.totalMarketingWeekly);
  HOUR_ANALYSIS_GROUPS.forEach((group) => {
    if (group.key === "other") return;
    pushHoursDiff(`${getHourAnalysisGroupShortLabel(group.key)} floor`, snapshotSummary.roleWeekly[group.key], currentSummary.roleWeekly[group.key]);
    ["full_time", "part_time"].forEach((commitment) => {
      const before = snapshot.expectations[group.key]?.[commitment]?.expected;
      const after = current.expectations[group.key]?.[commitment]?.expected;
      if (normalizeHourAnalysisNumber(before, 0) !== normalizeHourAnalysisNumber(after, 0)) {
        changes.push(`${getHourAnalysisGroupShortLabel(group.key)} ${getLaborEmploymentCommitmentLabel(commitment)} expected: ${formatHourAnalysisHours(before)} -> ${formatHourAnalysisHours(after)} hrs`);
      }
    });
  });
  if (snapshot.whatIfRows.length !== current.whatIfRows.length) {
    changes.push(`What-if rows: ${snapshot.whatIfRows.length} -> ${current.whatIfRows.length}`);
  }
  return changes.slice(0, 12);
}























export function normalizeHourAnalysisSettings(value = {}) {
  const source = isObjectRow(value) ? value : {};
  const laborModelSource = source.laborModel || source.labor_model || source.laborModelSettings || source.labor_model_settings;
  const thresholdSource = isObjectRow(source.thresholds || source.coverage || source.capacity)
    ? (source.thresholds || source.coverage || source.capacity)
    : {};
  const topLevelStaffingCapacity = source.staffing_capacity || source.staffingCapacity || source.staffingCapacitySettings;
  return {
    expectations: normalizeHourAnalysisExpectationMap(source.expectations),
    overrides: normalizeHourAnalysisOverrides(source.overrides),
    notes: normalizeHourAnalysisNotes(source.notes || source.justifications),
    splits: normalizeHourAnalysisSplits(source.splits || source.coverage_splits || source.coverageSplits),
    positionMovements: normalizeHourAnalysisPositionMovements(source.positionMovements || source.position_movements || source.movements || source.roleMovements || source.role_movements),
    whatIfRows: normalizeHourAnalysisWhatIfRows(source.whatIfRows || source.what_if_rows),
    thresholds: normalizeHourAnalysisThresholds(topLevelStaffingCapacity
      ? { ...thresholdSource, staffing_capacity: topLevelStaffingCapacity }
      : thresholdSource),
    laborModel: normalizeHourAnalysisLaborModel(laborModelSource),
    laborModelRoleColors: normalizeLaborModelRolePalette(
      source.laborModelRoleColors
        || source.labor_model_role_colors
        || source.roleColors
        || source.role_colors
        || laborModelSource?.roleColors
        || laborModelSource?.role_colors
    ),
    auditLog: normalizeHourAnalysisAuditLog(source.auditLog || source.audit_log),
  };
}

export function clearHourAnalysisPlanningState(value = {}) {
  const normalized = normalizeHourAnalysisSettings(value);
  const whatIfIds = new Set(
    normalized.whatIfRows
      .map((row) => String(row?.id || row?.employeeKey || "").trim())
      .filter(Boolean)
  );
  const nextNotes = { ...normalized.notes };
  const nextSplits = { ...normalized.splits };
  let removedWhatIfNotes = 0;
  let removedWhatIfSplits = 0;
  whatIfIds.forEach((id) => {
    if (Object.prototype.hasOwnProperty.call(nextNotes, id)) {
      delete nextNotes[id];
      removedWhatIfNotes += 1;
    }
    if (Object.prototype.hasOwnProperty.call(nextSplits, id)) {
      delete nextSplits[id];
      removedWhatIfSplits += 1;
    }
  });
  const removedWhatIfRows = normalized.whatIfRows.length;
  const removedPositionMovements = Object.keys(normalized.positionMovements || {}).length;
  const changed = Boolean(removedWhatIfRows || removedPositionMovements || removedWhatIfNotes || removedWhatIfSplits);
  return {
    settings: {
      ...normalized,
      notes: nextNotes,
      splits: nextSplits,
      positionMovements: {},
      whatIfRows: [],
    },
    summary: {
      changed,
      removedWhatIfRows,
      removedPositionMovements,
      removedWhatIfNotes,
      removedWhatIfSplits,
    },
  };
}



export function normalizeLaborCapacityModelRow(row = {}, fallbackSettings = {}) {
  const source = isObjectRow(row) ? row : {};
  const modelSettings = source.model_settings || source.modelSettings || source.settings || fallbackSettings;
  const createdAt = source.created_at || source.createdAt || null;
  const updatedAt = source.updated_at || source.updatedAt || createdAt || null;
  return {
    id: String(source.id || makeLaborCapacityModelTempId()).trim(),
    location_id: String(source.location_id || source.locationId || "").trim(),
    name: normalizeLaborCapacityModelName(source.name, LABOR_CAPACITY_MODEL_DEFAULT_NAME),
    description: String(source.description || "").trim(),
    model_settings: normalizeHourAnalysisSettings(modelSettings),
    is_active: Boolean(source.is_active ?? source.isActive),
    archived_at: source.archived_at || source.archivedAt || null,
    activated_at: source.activated_at || source.activatedAt || null,
    created_by_user_id: source.created_by_user_id || source.createdByUserId || null,
    created_by_name: source.created_by_name || source.createdByName || "",
    updated_by_user_id: source.updated_by_user_id || source.updatedByUserId || null,
    updated_by_name: source.updated_by_name || source.updatedByName || "",
    created_at: createdAt,
    updated_at: updatedAt,
  };
}

export function normalizeLaborCapacityModels(rows = [], fallbackSettings = {}) {
  return toObjectRows(rows)
    .map((row) => normalizeLaborCapacityModelRow(row, fallbackSettings))
    .sort((left, right) => {
      if (left.archived_at && !right.archived_at) return 1;
      if (!left.archived_at && right.archived_at) return -1;
      if (left.is_active && !right.is_active) return -1;
      if (!left.is_active && right.is_active) return 1;
      return String(right.updated_at || "").localeCompare(String(left.updated_at || ""));
    });
}

export function getActiveLaborCapacityModel(models = []) {
  return normalizeLaborCapacityModels(models).find((model) => model.is_active && !model.archived_at) || null;
}

export function applyLaborCapacityModelActivation(models = [], activeModelId = "") {
  const targetId = String(activeModelId || "").trim();
  return normalizeLaborCapacityModels(models).map((model) => ({
    ...model,
    is_active: Boolean(targetId && model.id === targetId && !model.archived_at),
    activated_at: targetId && model.id === targetId && !model.archived_at ? model.activated_at || new Date().toISOString() : model.activated_at,
  }));
}

export function buildDefaultLaborCapacityModelPayload({
  locationId = "",
  name = LABOR_CAPACITY_MODEL_DEFAULT_NAME,
  settings = {},
  actorUserId = null,
  actorName = "",
  isActive = true,
} = {}) {
  return {
    location_id: String(locationId || "").trim(),
    name: normalizeLaborCapacityModelName(name, LABOR_CAPACITY_MODEL_DEFAULT_NAME),
    model_settings: normalizeHourAnalysisSettings(settings),
    is_active: Boolean(isActive),
    activated_at: isActive ? new Date().toISOString() : null,
    created_by_user_id: actorUserId || null,
    created_by_name: actorName || "",
    updated_by_user_id: actorUserId || null,
    updated_by_name: actorName || "",
  };
}

export function selectStaffingCapacitySettings({
  models = [],
  editingModelId = "",
  editingSettings = {},
  legacySettings = {},
} = {}) {
  const normalizedModels = normalizeLaborCapacityModels(models);
  const activeModel = getActiveLaborCapacityModel(normalizedModels);
  if (!activeModel) return normalizeHourAnalysisSettings(legacySettings || editingSettings);
  if (String(activeModel.id) === String(editingModelId || "")) {
    return normalizeHourAnalysisSettings(editingSettings);
  }
  return normalizeHourAnalysisSettings(activeModel.model_settings);
}









export function buildOutOfPositionLaborSummary({ staffPlans = [], employees = [], weekStart = todayStr() } = {}) {
  const start = getLaborCapacityWeekStart(weekStart);
  const end = addDaysToDateString(start, 6);
  const employeeById = new Map();
  const employeeByName = new Map();
  toObjectRows(employees).forEach((employee) => {
    const id = getLaborEmployeeRowId(employee);
    if (id && !employeeById.has(String(id))) employeeById.set(String(id), employee);
    const name = normalizeEmployeeName(employee.full_name || employee.name || [employee.first_name, employee.last_name].filter(Boolean).join(" "));
    if (name && !employeeByName.has(name)) employeeByName.set(name, employee);
  });

  const rows = [];
  toObjectRows(staffPlans)
    .filter((plan) => {
      const planDate = String(plan.plan_date || plan.date || "").slice(0, 10);
      return planDate >= start && planDate <= end;
    })
    .forEach((plan) => {
      const planDate = String(plan.plan_date || plan.date || "").slice(0, 10);
      const date = new Date(`${planDate}T12:00:00`);
      const dayLabel = Number.isNaN(date.getTime())
        ? planDate
        : date.toLocaleDateString(undefined, { weekday: "short" });
      getStaffPlanEntries(plan).forEach((entry) => {
        const employeeNameKey = normalizeEmployeeName(entry.name);
        const entryLaborEmployeeId = String(entry.labor_employee_id || "").trim();
        const employee = entryLaborEmployeeId
          ? employeeById.get(entryLaborEmployeeId)
          : employeeNameKey
            ? employeeByName.get(employeeNameKey)
            : null;
        const matchMethod = employee
          ? entryLaborEmployeeId ? "labor_employee_id" : "name"
          : "unmatched";
        const homeRoleKey = employee ? getHourAnalysisGroupKey(employee) : "";
        const workedRoleKey = normalizeStaffingRoleKey(entry.position);
        const homeCompare = getOutOfPositionCompareKey(homeRoleKey);
        const workedCompare = getOutOfPositionCompareKey(workedRoleKey);
        const isUnclassified = !employee || !homeRoleKey || !workedRoleKey;
        const isMismatch = !isUnclassified && homeCompare !== workedCompare;
        rows.push({
          id: `${plan.id || planDate || "plan"}-${entry.id}`,
          labor_employee_id: entryLaborEmployeeId || getLaborEmployeeRowId(employee) || "",
          match_method: matchMethod,
          employee_name: entry.name || "Unassigned",
          date: planDate,
          day_label: dayLabel,
          home_role_key: homeRoleKey,
          home_role_label: getOutOfPositionRoleLabel(homeRoleKey),
          worked_role_key: workedRoleKey,
          worked_role_label: getOutOfPositionRoleLabel(workedRoleKey),
          shift_label: [entry.shift_start, entry.shift_end].filter(Boolean).join("-") || String(plan.shift || "").toUpperCase() || "Shift",
          shift: String(plan.shift || "").toUpperCase(),
          hours: normalizeHourAnalysisNumber(entry.hours, 0),
          classification: isUnclassified ? "unclassified" : isMismatch ? "mismatch" : "matched",
          reason: !employee ? "Employee not matched to roster" : !homeRoleKey ? "Home role missing" : !workedRoleKey ? "Worked role missing" : "",
        });
      });
    });

  const mismatchRows = rows.filter((row) => row.classification === "mismatch");
  const unclassifiedRows = rows.filter((row) => row.classification === "unclassified");
  const mismatchBuckets = mismatchRows.reduce((acc, row) => {
    const key = `${row.home_role_label} -> ${row.worked_role_label}`;
    const bucket = acc[key] || { key, shifts: 0, hours: 0 };
    bucket.shifts += 1;
    bucket.hours = normalizeHourAnalysisNumber(bucket.hours + row.hours, 0);
    acc[key] = bucket;
    return acc;
  }, {});

  return {
    weekStart: start,
    weekEnd: end,
    totalShifts: mismatchRows.length,
    totalHours: normalizeHourAnalysisNumber(mismatchRows.reduce((sum, row) => sum + row.hours, 0), 0),
    unclassifiedShifts: unclassifiedRows.length,
    unclassifiedHours: normalizeHourAnalysisNumber(unclassifiedRows.reduce((sum, row) => sum + row.hours, 0), 0),
    topMismatches: Object.values(mismatchBuckets).sort((left, right) => (right.shifts - left.shifts) || (right.hours - left.hours)).slice(0, 5),
    rows: [...mismatchRows, ...unclassifiedRows].sort((left, right) => {
      const leftPriority = left.classification === "mismatch" ? 0 : 1;
      const rightPriority = right.classification === "mismatch" ? 0 : 1;
      if (leftPriority !== rightPriority) return leftPriority - rightPriority;
      return `${left.date}-${left.employee_name}`.localeCompare(`${right.date}-${right.employee_name}`);
    }),
  };
}

export function getLaborCapacityWeekStart(dateValue = todayStr()) {
  const date = new Date(`${String(dateValue || todayStr()).slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return todayStr();
  const day = date.getDay();
  const mondayOffset = day === 0 ? -6 : 1 - day;
  date.setDate(date.getDate() + mondayOffset);
  return date.toISOString().slice(0, 10);
}



















export function buildHourAnalysisCapacityRowVisualModel(row = {}, groupDisplay = null) {
  const defaultHasRange = HOUR_ANALYSIS_FRONTLINE_GROUP_KEYS.has(row.key);
  const expected = normalizeHourAnalysisNumber(row.expected, 0);
  const floor = normalizeHourAnalysisNumber(row.requiredWeekly, 0);
  const capacityStandard = row.capacityStandard || buildHourAnalysisCapacityStandard(floor, defaultHasRange ? HOUR_ANALYSIS_RECOMMENDED_RESERVE_PERCENT : 0);
  const isFrontline = normalizeHourAnalysisNumber(capacityStandard.targetBufferPercent, 0) > 0;
  const target = normalizeHourAnalysisNumber(row.targetWeekly || floor, floor);
  const targetLow = isFrontline ? normalizeHourAnalysisNumber(capacityStandard.healthyLowWeekly, target) : target;
  const targetHigh = isFrontline ? normalizeHourAnalysisNumber(capacityStandard.healthyHighWeekly, targetLow) : target;
  const targetMid = normalizeHourAnalysisNumber(target, floor);
  const deltaToTarget = normalizeHourAnalysisDelta(expected - targetMid);
  const deltaToRange = isFrontline
    ? expected < targetLow
      ? normalizeHourAnalysisDelta(expected - targetLow)
      : expected > targetHigh
        ? normalizeHourAnalysisDelta(expected - targetHigh)
        : 0
    : deltaToTarget;
  const deltaToFloor = normalizeHourAnalysisDelta(expected - floor);
  const rawDelta = isFrontline ? formatHourAnalysisCapacityRangeDelta(expected, capacityStandard) : formatHourAnalysisCapacityDelta(deltaToTarget);
  const measurementValues = [expected, floor, targetMid, targetLow, targetHigh]
    .map((value) => normalizeHourAnalysisNumber(value, 0))
    .filter((value) => Number.isFinite(value));
  const lowestWeekly = measurementValues.length ? Math.min(...measurementValues) : 0;
  const highestWeekly = measurementValues.length ? Math.max(...measurementValues, 1) : 1;
  const domainPadding = 10;
  const domainMin = Math.max(0, normalizeHourAnalysisNumber(lowestWeekly - domainPadding, 0));
  const domainMax = normalizeHourAnalysisNumber(Math.max(highestWeekly + domainPadding, domainMin + 20), domainMin + 20);
  const domainWidth = Math.max(1, domainMax - domainMin);
  const valueToPct = (value, min = 0, max = 100) => clampHourAnalysisPercent(((normalizeHourAnalysisNumber(value, 0) - domainMin) / domainWidth) * 100, min, max);
  const maxWeekly = domainMax;
  const expectedPct = valueToPct(expected, 1.5, 98.5);
  const floorPct = valueToPct(floor);
  const targetPct = valueToPct(targetMid);
  const targetLowPct = valueToPct(targetLow);
  const targetHighPct = valueToPct(targetHigh);
  const labelPct = (pct) => clampHourAnalysisPercent(pct, 11, 87);
  const rangeLabelPct = labelPct((targetLowPct + targetHighPct) / 2);
  const hasTargetRange = isFrontline && targetHigh > targetLow + 0.05;
  const tolerancePercent = normalizeHourAnalysisNumber(capacityStandard.tolerancePercent, HOUR_ANALYSIS_DEFAULT_TOLERANCE_PERCENT);
  const toleranceState = buildHourAnalysisCapacityToleranceState({
    expected,
    floor,
    targetLow,
    targetHigh,
    target: targetMid,
    hasTargetRange,
    tolerancePercent,
  });
  const isOutsideButTolerated = toleranceState.withinTolerance && !["aligned", "in-range"].includes(toleranceState.relation) && toleranceState.delta !== 0;
  const delta = isOutsideButTolerated
    ? {
      value: formatHourAnalysisSignedDelta(toleranceState.delta),
      tone: "healthy",
      label: "Within tolerance",
    }
    : rawDelta;
  const hasSeparateTargetMetric = hasTargetRange || Math.abs(normalizeHourAnalysisDelta(targetMid - floor)) > 0.05;
  const floorMetricLabel = hasSeparateTargetMetric ? "Floor" : "Floor / Target";
  const makeDimensionLine = ({ key, label, start, end, tone = "neutral" }) => {
    const startPct = valueToPct(start);
    const endPct = valueToPct(end);
    const leftPct = Math.min(startPct, endPct);
    const rawWidthPct = Math.abs(endPct - startPct);
    const midpointPct = valueToPct((normalizeHourAnalysisNumber(start, 0) + normalizeHourAnalysisNumber(end, 0)) / 2);
    return {
      key,
      label,
      tone,
      leftPct,
      widthPct: Math.max(rawWidthPct, 1.2),
      midpointPct,
      labelPct: clampHourAnalysisPercent(midpointPct, 12, 88),
      isZero: rawWidthPct < 0.8,
    };
  };
  const tone = isOutsideButTolerated
    ? "healthy"
    : isFrontline
      ? deltaToRange < 0
        ? "short"
        : deltaToRange > 0
          ? "surplus"
          : "healthy"
      : deltaToTarget < 0
        ? "short"
        : deltaToTarget > 0
          ? "surplus"
          : "healthy";
  const statusLabel = isOutsideButTolerated
    ? "Within tolerance"
    : isFrontline
      ? expected < targetLow
        ? (deltaToFloor < 0 ? "Short" : "Below range")
        : expected > targetHigh
          ? "Over range"
          : expected > targetMid
            ? "Over target"
            : "In range"
      : deltaToFloor < 0
        ? "Short"
        : deltaToFloor > 0
          ? "Above floor"
          : "In range";
  const statusDetail = isOutsideButTolerated
    ? `${formatHourAnalysisHoursWithUnit(Math.abs(toleranceState.delta))} ${toleranceState.delta < 0 ? "below" : "above"} ${toleranceState.boundaryLabel}, within ${formatHourAnalysisHoursWithUnit(toleranceState.toleranceHours)} tolerance`
    : isFrontline
      ? expected < targetLow
        ? deltaToFloor < 0
          ? `${formatHourAnalysisHoursWithUnit(Math.abs(deltaToRange))} below lower range (${formatHourAnalysisHoursWithUnit(Math.abs(deltaToFloor))} below floor)`
          : `${formatHourAnalysisHoursWithUnit(Math.abs(deltaToRange))} below lower range`
        : expected > targetHigh
          ? `${formatHourAnalysisHoursWithUnit(expected - targetHigh)} over upper range`
          : expected > targetMid
            ? `${formatHourAnalysisHoursWithUnit(expected - targetMid)} over target, still in range`
            : `Inside ${formatHourAnalysisHours(targetLow)}-${formatHourAnalysisHours(targetHigh)} hr range`
      : deltaToFloor < 0
        ? `${formatHourAnalysisHoursWithUnit(Math.abs(deltaToFloor))} below floor`
        : deltaToFloor > 0
          ? `${formatHourAnalysisHoursWithUnit(deltaToFloor)} above floor`
          : "Expected equals floor";
  const primaryDelta = isFrontline ? deltaToRange : deltaToTarget;
  const magnitudeBase = Math.max(8, Math.max(expected, targetHigh, targetMid, floor, 1) * 0.22);
  const magnitudeRatio = Math.min(1, Math.abs(primaryDelta || deltaToFloor || deltaToTarget) / magnitudeBase);
  const measurementIntensity = normalizeHourAnalysisNumber(0.34 + (magnitudeRatio * 0.48), 2);
  const targetDeltaLabel = deltaToTarget < 0
    ? `${formatHourAnalysisHours(Math.abs(deltaToTarget))} hrs short to target`
    : deltaToTarget > 0
      ? `${formatHourAnalysisHours(deltaToTarget)} hrs over target`
      : "aligned to target";
  const floorDeltaLabel = deltaToFloor < 0
    ? `${formatHourAnalysisHours(Math.abs(deltaToFloor))} hrs short to floor`
    : deltaToFloor > 0
      ? `${formatHourAnalysisHours(deltaToFloor)} hrs over floor`
      : "aligned to operational floor";
  const topLabels = [
    {
      key: "floor",
      label: "Floor",
      value: `${formatHourAnalysisHours(floor)} hrs`,
      pct: labelPct(floorPct),
      markerPct: floorPct,
      lane: 0,
      tone: "floor",
    },
    hasTargetRange ? {
      key: "lower-range",
      label: "Lower range",
      value: `${formatHourAnalysisHours(targetLow)} hrs`,
      pct: labelPct(targetLowPct),
      markerPct: targetLowPct,
      lane: 0,
      tone: "target",
    } : null,
    hasTargetRange ? {
      key: "target",
      label: "Target",
      value: `${formatHourAnalysisHours(targetMid)} hrs`,
      pct: labelPct(targetPct),
      markerPct: targetPct,
      lane: 0,
      tone: "target",
    } : null,
    hasTargetRange ? {
      key: "upper-range",
      label: "Upper range",
      value: `${formatHourAnalysisHours(targetHigh)} hrs`,
      pct: labelPct(targetHighPct),
      markerPct: targetHighPct,
      lane: 0,
      tone: "target",
    } : null,
  ].filter(Boolean);
  const dimensionLines = [
    makeDimensionLine({
      key: "expected",
      label: `${formatHourAnalysisHours(expected)} hrs expected`,
      start: domainMin,
      end: expected,
      tone: isOutsideButTolerated ? "neutral" : deltaToFloor < 0 ? "short" : "surplus",
    }),
    makeDimensionLine({
      key: "floor",
      label: floorDeltaLabel,
      start: expected,
      end: floor,
      tone: isOutsideButTolerated ? "neutral" : deltaToFloor < 0 ? "short" : deltaToFloor > 0 ? "surplus" : "neutral",
    }),
    hasTargetRange ? makeDimensionLine({
      key: "target",
      label: targetDeltaLabel,
      start: expected,
      end: targetMid,
      tone: isOutsideButTolerated ? "neutral" : deltaToTarget < 0 ? "short" : deltaToTarget > 0 ? "surplus" : "neutral",
    }) : null,
  ].filter(Boolean);
  if (hasTargetRange) {
    dimensionLines.push(makeDimensionLine({
      key: "target-range",
      label: `${formatHourAnalysisHours(targetLow)}-${formatHourAnalysisHours(targetHigh)} hrs target range`,
      start: targetLow,
      end: targetHigh,
      tone: "range",
    }));
  }
  if (hasTargetRange && expected > targetHigh && targetHigh > 0) {
    dimensionLines.push(makeDimensionLine({
      key: "overage",
      label: `${formatHourAnalysisHours(expected - targetHigh)} hrs over upper range`,
      start: targetHigh,
      end: expected,
      tone: "surplus",
    }));
  }

  return {
    key: row.key || "",
    roleLabel: getConfiguredHourAnalysisGroupShortLabel(row.key, groupDisplay),
    isFrontline,
    expected,
    floor,
    target,
    targetLow,
    targetHigh,
    hasTargetRange,
    hasSeparateTargetMetric,
    floorMetricLabel,
    tolerancePercent,
    toleranceHours: toleranceState.toleranceHours,
    withinTolerance: isOutsideButTolerated,
    domainMin,
    domainMax,
    maxWeekly,
    deltaToTarget,
    deltaToRange,
    deltaToFloor,
    tone,
	    delta,
	    statusLabel,
	    statusDetail,
	    measurementIntensity,
    expectedPct,
    floorPct,
    targetPct,
    targetLowPct,
    targetHighPct,
    topLabels,
    dimensionLines,
    floorLabelPct: labelPct(floorPct),
    targetLabelPct: labelPct(targetPct),
    targetRangeLabelPct: rangeLabelPct,
    bufferLeftPct: isFrontline ? targetLowPct : floorPct,
    bufferWidthPct: isFrontline ? Math.max(0, targetHighPct - targetLowPct) : 0,
  };
}




export function buildStaffingCapacityBarChartModel(rows = [], groupDisplay = null) {
  const visualRows = (Array.isArray(rows) ? rows : []).map((row) => buildHourAnalysisCapacityRowVisualModel(row, groupDisplay));
  const rawMax = visualRows.reduce((max, visual) => Math.max(
    max,
    visual.expected,
    visual.floor,
    visual.targetLow,
    visual.target,
    visual.targetHigh,
  ), 0);
  const chartMax = getNiceStaffingCapacityChartMax(rawMax);
  const ticks = [1, 0.75, 0.5, 0.25, 0].map((ratio) => {
    const value = normalizeHourAnalysisNumber(chartMax * ratio, 0);
    return {
      key: `tick-${ratio}`,
      value,
      label: formatStaffingCapacityBarHours(value),
      pct: getStaffingCapacityChartPct(value, chartMax),
    };
  });
  const chartRows = visualRows.map((visual) => {
    const expectedPct = getStaffingCapacityChartPct(visual.expected, chartMax);
    const demandPct = getStaffingCapacityChartPct(visual.floor, chartMax);
    const targetLowPct = getStaffingCapacityChartPct(visual.targetLow, chartMax);
    const targetHighPct = getStaffingCapacityChartPct(visual.targetHigh, chartMax);
    return {
      ...visual,
      demand: visual.floor,
      chartMax,
      expectedPct,
      demandPct,
      expectedBarPct: visual.expected > 0 ? Math.max(expectedPct, 2) : 0,
      demandBarPct: visual.floor > 0 ? Math.max(demandPct, 2) : 0,
      targetLowPct,
      targetHighPct,
      targetBandBottomPct: targetLowPct,
      targetBandHeightPct: visual.hasTargetRange ? Math.max(0, targetHighPct - targetLowPct) : 0,
      expectedLabel: formatStaffingCapacityBarHours(visual.expected),
      demandLabel: formatStaffingCapacityBarHours(visual.floor),
      targetLowLabel: formatStaffingCapacityBarHours(visual.targetLow),
      targetHighLabel: formatStaffingCapacityBarHours(visual.targetHigh),
    };
  });
  const summary = chartRows.reduce((acc, row) => {
    if (row.tone === "short") acc.short += 1;
    else if (row.tone === "surplus") acc.over += 1;
    else acc.inRange += 1;
    if (row.withinTolerance) acc.withinTolerance += 1;
    return acc;
  }, { short: 0, inRange: 0, over: 0, withinTolerance: 0 });
  return {
    chartMax,
    ticks,
    rows: chartRows,
    summary,
  };
}

export function buildHourAnalysisModel({ rosterRows = [], settings = {} } = {}) {
  const normalizedSettings = normalizeHourAnalysisSettings(settings);
  const laborModelSummary = buildHourAnalysisLaborModelSummary(normalizedSettings.laborModel);
  const activeRows = toObjectRows(rosterRows).filter((row) => isLaborEmployeeActive(row));
  const makeEmptyBucket = () => ({ fullTime: 0, partTime: 0, unassigned: 0, total: 0, whatIfFullTime: 0, whatIfPartTime: 0, whatIfTotal: 0 });
  const headcountByGroup = Object.fromEntries(HOUR_ANALYSIS_GROUPS.map((group) => [group.key, makeEmptyBucket()]));
  const makeWeeklyBucket = () => ({
    fullTime: makeHourAnalysisRangeTotals(),
    partTime: makeHourAnalysisRangeTotals(),
    total: makeHourAnalysisRangeTotals(),
    whatIfFullTime: makeHourAnalysisRangeTotals(),
    whatIfPartTime: makeHourAnalysisRangeTotals(),
    whatIfTotal: makeHourAnalysisRangeTotals(),
  });
  const weeklyHoursByGroup = Object.fromEntries(HOUR_ANALYSIS_GROUPS.map((group) => [group.key, makeWeeklyBucket()]));
  const activeRowsByEmployeeKey = new Map();
  activeRows.forEach((row) => {
    const employeeKey = getHourAnalysisEmployeeKey(row);
    if (employeeKey && !activeRowsByEmployeeKey.has(employeeKey)) activeRowsByEmployeeKey.set(employeeKey, row);
  });

  const addHeadcount = ({ groupKey, commitment, isWhatIf = false, delta = 1 }) => {
    const target = headcountByGroup[groupKey] || headcountByGroup.other;
    const amount = normalizeHourAnalysisDelta(Number(delta));
    if (commitment === "full_time") target[isWhatIf ? "whatIfFullTime" : "fullTime"] += amount;
    else if (commitment === "part_time") target[isWhatIf ? "whatIfPartTime" : "partTime"] += amount;
    else if (!isWhatIf) target.unassigned += amount;
    if (isWhatIf) target.whatIfTotal += amount;
    else target.total += amount;
  };

  const addWeeklyHours = ({ groupKey, commitment, range, isWhatIf = false, delta = 1 }) => {
    const target = weeklyHoursByGroup[groupKey] || weeklyHoursByGroup.other;
    if (commitment === "full_time") {
      addHourAnalysisRangeDelta(isWhatIf ? target.whatIfFullTime : target.fullTime, range, delta);
    } else if (commitment === "part_time") {
      addHourAnalysisRangeDelta(isWhatIf ? target.whatIfPartTime : target.partTime, range, delta);
    }
    addHourAnalysisRangeDelta(isWhatIf ? target.whatIfTotal : target.total, range, delta);
  };

  const employeeRows = activeRows.map((row) => {
    const employeeKey = getHourAnalysisEmployeeKey(row);
    const sourcePositionTitle = formatLaborPositionTitle(row.position_title || row.position || "");
    const sourceGroupKey = getHourAnalysisGroupKey(row);
    const commitment = readLaborEmploymentCommitment(row);
    const overrideRange = employeeKey ? normalizeHourAnalysisOverrideRange(normalizedSettings.overrides[employeeKey]) : {};
    const sourceInheritedRange = commitment ? normalizedSettings.expectations[sourceGroupKey]?.[commitment] ?? makeHourAnalysisRangeTotals() : makeHourAnalysisRangeTotals();
    const sourcePreferredRange = mergeHourAnalysisRange(sourceInheritedRange, overrideRange);
    const movement = employeeKey ? normalizeHourAnalysisPositionMovement(normalizedSettings.positionMovements[employeeKey]) : {};
    const targetPositionTitle = movement.position_title || sourcePositionTitle;
    const isMovement = Boolean(movement.position_title && normalizePositionTitle(movement.position_title) !== normalizePositionTitle(sourcePositionTitle));
    const groupKey = isMovement ? movement.group_key || getHourAnalysisGroupKey({ position_title: targetPositionTitle }) : sourceGroupKey;
    const effectiveRow = { ...row, position_title: targetPositionTitle, position: targetPositionTitle };
    const inheritedRange = commitment ? normalizedSettings.expectations[groupKey]?.[commitment] ?? makeHourAnalysisRangeTotals() : makeHourAnalysisRangeTotals();
    const preferredRange = mergeHourAnalysisRange(inheritedRange, overrideRange);
    const note = employeeKey ? String(normalizedSettings.notes[employeeKey] || "").trim() : "";
    const sourceSplit = resolveHourAnalysisCoverageSplit({
      row,
      groupKey: sourceGroupKey,
      preferredHours: sourcePreferredRange.expected,
      split: employeeKey ? normalizedSettings.splits[employeeKey] : {},
    });
    addHeadcount({ groupKey: sourceGroupKey, commitment });
    addWeeklyHours({ groupKey: sourceGroupKey, commitment, range: buildHourAnalysisRangeFromHours(sourceSplit.primary_hours) });
    if (sourceSplit.floor_group && sourceSplit.floor_hours > 0) {
      addWeeklyHours({ groupKey: sourceSplit.floor_group, commitment, range: buildHourAnalysisRangeFromHours(sourceSplit.floor_hours) });
    }
    const split = resolveHourAnalysisCoverageSplit({
      row: effectiveRow,
      groupKey,
      preferredHours: preferredRange.expected,
      split: employeeKey ? normalizedSettings.splits[employeeKey] : {},
    });
    if (isMovement) {
      addHeadcount({ groupKey: sourceGroupKey, commitment, isWhatIf: true, delta: -1 });
      addWeeklyHours({ groupKey: sourceGroupKey, commitment, range: buildHourAnalysisRangeFromHours(sourceSplit.primary_hours), isWhatIf: true, delta: -1 });
      if (sourceSplit.floor_group && sourceSplit.floor_hours > 0) {
        addWeeklyHours({ groupKey: sourceSplit.floor_group, commitment, range: buildHourAnalysisRangeFromHours(sourceSplit.floor_hours), isWhatIf: true, delta: -1 });
      }
      addHeadcount({ groupKey, commitment, isWhatIf: true });
      addWeeklyHours({ groupKey, commitment, range: buildHourAnalysisRangeFromHours(split.primary_hours), isWhatIf: true });
      if (split.floor_group && split.floor_hours > 0) {
        addWeeklyHours({ groupKey: split.floor_group, commitment, range: buildHourAnalysisRangeFromHours(split.floor_hours), isWhatIf: true });
      }
    }
    return {
      ...row,
      employeeKey,
      sourcePositionTitle,
      sourceGroupKey,
      sourceGroupLabel: getHourAnalysisGroupLabel(sourceGroupKey),
      position_title: targetPositionTitle,
      groupKey,
      groupLabel: getHourAnalysisGroupLabel(groupKey),
      commitment,
      inheritedRange,
      overrideRange,
      preferredRange,
      inheritedHours: inheritedRange.expected,
      overrideHours: Object.prototype.hasOwnProperty.call(overrideRange, "expected") ? overrideRange.expected : null,
      preferredHours: preferredRange.expected,
      note,
      split,
      isOverride: Object.keys(overrideRange).length > 0,
      isSplit: Boolean(split.floor_group && split.floor_hours > 0),
      isMovement,
      isWhatIf: false,
    };
  });

  const whatIfRows = normalizedSettings.whatIfRows.map((row) => {
    const isMovement = row.scenario_type === "move";
    const sourceEmployeeKey = String(row.source_employee_key || "").trim();
    const sourceRow = isMovement && sourceEmployeeKey ? activeRowsByEmployeeKey.get(sourceEmployeeKey) : null;
    let sourcePlan = null;
    if (sourceRow) {
      const sourceGroupKey = getHourAnalysisGroupKey(sourceRow);
      const sourceCommitment = readLaborEmploymentCommitment(sourceRow) || row.source_employment_commitment || "full_time";
      const sourceInheritedRange = sourceCommitment ? normalizedSettings.expectations[sourceGroupKey]?.[sourceCommitment] ?? makeHourAnalysisRangeTotals() : makeHourAnalysisRangeTotals();
      const sourceOverrideRange = normalizeHourAnalysisOverrideRange(normalizedSettings.overrides[sourceEmployeeKey]);
      const sourcePreferredRange = mergeHourAnalysisRange(sourceInheritedRange, sourceOverrideRange);
      const sourceSplit = resolveHourAnalysisCoverageSplit({
        row: sourceRow,
        groupKey: sourceGroupKey,
        preferredHours: sourcePreferredRange.expected,
        split: normalizedSettings.splits[sourceEmployeeKey] || {},
      });
      sourcePlan = {
        employeeKey: sourceEmployeeKey,
        full_name: sourceRow.full_name || [sourceRow.first_name, sourceRow.last_name].filter(Boolean).join(" ") || row.source_full_name || "Moved employee",
        position_title: formatLaborPositionTitle(sourceRow.position_title || sourceRow.position || row.source_position_title || ""),
        groupKey: sourceGroupKey,
        groupLabel: getHourAnalysisGroupLabel(sourceGroupKey),
        commitment: sourceCommitment,
        preferredHours: sourcePreferredRange.expected,
        split: sourceSplit,
      };
      addHeadcount({ groupKey: sourceGroupKey, commitment: sourceCommitment, isWhatIf: true, delta: -1 });
      addWeeklyHours({ groupKey: sourceGroupKey, commitment: sourceCommitment, range: buildHourAnalysisRangeFromHours(sourceSplit.primary_hours), isWhatIf: true, delta: -1 });
      if (sourceSplit.floor_group && sourceSplit.floor_hours > 0) {
        addWeeklyHours({ groupKey: sourceSplit.floor_group, commitment: sourceCommitment, range: buildHourAnalysisRangeFromHours(sourceSplit.floor_hours), isWhatIf: true, delta: -1 });
      }
    }
    const groupKey = row.group_key || getHourAnalysisGroupKey(row);
    const commitment = readLaborEmploymentCommitment(row) || "full_time";
    const inheritedRange = normalizedSettings.expectations[groupKey]?.[commitment] ?? makeHourAnalysisRangeTotals();
    const overrideRange = normalizeHourAnalysisOverrideRange(row.hour_overrides);
    const preferredRange = mergeHourAnalysisRange(inheritedRange, overrideRange);
    const split = resolveHourAnalysisCoverageSplit({
      row,
      groupKey,
      preferredHours: preferredRange.expected,
      split: normalizedSettings.splits[row.id] || row.split,
    });
    addHeadcount({ groupKey, commitment, isWhatIf: true });
    addWeeklyHours({ groupKey, commitment, range: buildHourAnalysisRangeFromHours(split.primary_hours), isWhatIf: true });
    if (split.floor_group && split.floor_hours > 0) {
      addWeeklyHours({ groupKey: split.floor_group, commitment, range: buildHourAnalysisRangeFromHours(split.floor_hours), isWhatIf: true });
    }
    return {
      id: row.id,
      employeeKey: row.id,
      scenarioType: row.scenario_type,
      isMovement,
      sourceEmployeeKey,
      sourcePlan,
      sourceFullName: sourcePlan?.full_name || row.source_full_name || "",
      sourcePositionTitle: formatLaborPositionTitle(sourcePlan?.position_title || row.source_position_title || ""),
      sourceGroupKey: sourcePlan?.groupKey || row.source_group_key || "",
      sourceGroupLabel: sourcePlan?.groupLabel || getHourAnalysisGroupLabel(row.source_group_key || "other"),
      sourceCommitment: sourcePlan?.commitment || row.source_employment_commitment || "",
      sourcePreferredHours: sourcePlan?.preferredHours ?? null,
      sourceMissing: isMovement && !sourcePlan,
      full_name: row.full_name,
      position_title: formatLaborPositionTitle(row.position_title),
      groupKey,
      groupLabel: getHourAnalysisGroupLabel(groupKey),
      commitment,
      employment_commitment: commitment,
      inheritedRange,
      overrideRange,
      preferredRange,
      inheritedHours: inheritedRange.expected,
      overrideHours: Object.prototype.hasOwnProperty.call(overrideRange, "expected") ? overrideRange.expected : null,
      preferredHours: preferredRange.expected,
      note: normalizedSettings.notes[row.id] || row.note || "",
      split,
      isOverride: Object.keys(overrideRange).length > 0,
      isSplit: Boolean(split.floor_group && split.floor_hours > 0),
      isWhatIf: true,
    };
  });

  const headcountRows = HOUR_ANALYSIS_GROUPS
    .map((group) => {
      const counts = headcountByGroup[group.key] || makeEmptyBucket();
      return {
        key: group.key,
        label: group.label,
        ...counts,
        projectedFullTime: counts.fullTime + counts.whatIfFullTime,
        projectedPartTime: counts.partTime + counts.whatIfPartTime,
        projectedTotal: counts.total + counts.whatIfTotal,
      };
    })
    .filter((row) => row.key !== "other" || row.total || row.whatIfTotal || row.unassigned);

  const weeklyRows = HOUR_ANALYSIS_GROUPS
    .map((group) => {
      const hours = weeklyHoursByGroup[group.key] || makeWeeklyBucket();
      const projected = sumHourAnalysisRanges(hours.total, hours.whatIfTotal);
      const legacyDailySkeleton = normalizeHourAnalysisNumber(normalizedSettings.thresholds.daily_skeleton[group.key], 0);
      const requiredWeekly = laborModelSummary.hasRows
        ? normalizeHourAnalysisNumber(laborModelSummary.roleWeekly[group.key] || 0, 0)
        : normalizeHourAnalysisNumber(legacyDailySkeleton * 7, 0);
      const requiredDaily = normalizeHourAnalysisNumber(requiredWeekly / 7, 0);
      const roleCapacitySettings = getStaffingCapacityRoleSettings(normalizedSettings.thresholds.staffing_capacity, group.key);
      const reliefPercent = roleCapacitySettings.targetBufferPercent;
      const capacityStandard = buildHourAnalysisCapacityStandard(requiredWeekly, reliefPercent, roleCapacitySettings);
      const isFrontline = reliefPercent > 0;
      const targetWeekly = capacityStandard.targetWeekly;
      const expectedHireHours = normalizeHourAnalysisNumber(
        normalizedSettings.expectations[group.key]?.full_time?.expected,
        DEFAULT_HOUR_ANALYSIS_EXPECTATIONS[group.key]?.full_time?.expected || HOUR_ANALYSIS_FULL_TIME_HIRE_EQUIVALENT_HOURS,
      );
      const expectedGapToTarget = normalizeHourAnalysisDelta(projected.expected - targetWeekly);
      const hireDeficitHours = Math.max(0, normalizeHourAnalysisDelta(targetWeekly - projected.expected));
      const recommendedFullTimeHires = hireDeficitHours > 0 && expectedHireHours > 0 ? Math.ceil(hireDeficitHours / expectedHireHours) : 0;
      const recommendedFullTimeEquivalent = hireDeficitHours > 0 && expectedHireHours > 0 ? normalizeHourAnalysisNumber(hireDeficitHours / expectedHireHours, 0) : 0;
      return {
        key: group.key,
        label: group.label,
        ...hours,
        projected,
        min: projected.min,
        expected: projected.expected,
        max: projected.max,
        requiredDaily,
        requiredWeekly,
        reliefPercent,
        targetWeekly,
        capacityStandard,
        expectedGapToTarget,
        hireDeficitHours,
        expectedHireHours,
        isFrontline,
        recommendedFullTimeHires,
        recommendedFullTimeEquivalent,
        recommendedHireHours: normalizeHourAnalysisNumber(recommendedFullTimeHires * expectedHireHours, 0),
        capacityStatus: buildHourAnalysisCapacityStatus({ requiredWeekly, targetWeekly, capacity: projected, standard: capacityStandard }),
      };
    })
    .filter((row) => row.key !== "other" || row.total.expected || row.whatIfTotal.expected || row.requiredWeekly);

  const totals = weeklyRows.reduce((acc, row) => {
    addHourAnalysisRange(acc.fullTime, row.fullTime);
    addHourAnalysisRange(acc.partTime, row.partTime);
    addHourAnalysisRange(acc.total, row.total);
    addHourAnalysisRange(acc.whatIfFullTime, row.whatIfFullTime);
    addHourAnalysisRange(acc.whatIfPartTime, row.whatIfPartTime);
    addHourAnalysisRange(acc.whatIfTotal, row.whatIfTotal);
    return acc;
  }, {
    fullTime: makeHourAnalysisRangeTotals(),
    partTime: makeHourAnalysisRangeTotals(),
    total: makeHourAnalysisRangeTotals(),
    whatIfFullTime: makeHourAnalysisRangeTotals(),
    whatIfPartTime: makeHourAnalysisRangeTotals(),
    whatIfTotal: makeHourAnalysisRangeTotals(),
  });
  const projectedFullTime = sumHourAnalysisRanges(totals.fullTime, totals.whatIfFullTime);
  const projectedPartTime = sumHourAnalysisRanges(totals.partTime, totals.whatIfPartTime);
  const projectedTotal = sumHourAnalysisRanges(totals.total, totals.whatIfTotal);
  const legacyRequiredDaily = HOUR_ANALYSIS_GROUPS.reduce((sum, group) => sum + normalizeHourAnalysisNumber(normalizedSettings.thresholds.daily_skeleton[group.key], 0), 0);
  const requiredWeekly = laborModelSummary.hasRows
    ? normalizeHourAnalysisNumber(laborModelSummary.totalWeekly, 0)
    : normalizeHourAnalysisNumber(legacyRequiredDaily * 7, 0);
  const requiredDaily = normalizeHourAnalysisNumber(requiredWeekly / 7, 0);
  const capacityStandard = combineHourAnalysisCapacityStandards(weeklyRows);
  const targetWeekly = capacityStandard.targetWeekly;
  const expectedGapToTarget = normalizeHourAnalysisDelta(projectedTotal.expected - targetWeekly);
  const hireDeficitHours = Math.max(0, normalizeHourAnalysisDelta(targetWeekly - projectedTotal.expected));
  const fullTimeEquivalentHires = hireDeficitHours > 0 ? normalizeHourAnalysisNumber(hireDeficitHours / HOUR_ANALYSIS_FULL_TIME_HIRE_EQUIVALENT_HOURS, 0) : 0;
  const fullTimeHireCount = hireDeficitHours > 0 ? Math.max(1, Math.round(hireDeficitHours / HOUR_ANALYSIS_FULL_TIME_HIRE_EQUIVALENT_HOURS)) : 0;
  const hiringRecommendations = weeklyRows
    .filter((row) => row.recommendedFullTimeHires > 0)
    .map((row) => ({
      key: row.key,
      label: row.label,
      shortHours: row.hireDeficitHours,
      hireCount: row.recommendedFullTimeHires,
      hireEquivalent: row.recommendedFullTimeEquivalent,
      hireHours: row.recommendedHireHours,
      expectedHireHours: row.expectedHireHours,
      isFrontline: row.isFrontline,
    }));
  const roleDeficitHours = normalizeHourAnalysisNumber(hiringRecommendations.reduce((sum, row) => sum + row.shortHours, 0), 0);
  const roleSurplusRows = weeklyRows
    .filter((row) => row.expectedGapToTarget > 0)
    .map((row) => ({
      key: row.key,
      label: row.label,
      surplusHours: row.expectedGapToTarget,
    }));
  const roleSurplusHours = normalizeHourAnalysisNumber(roleSurplusRows.reduce((sum, row) => sum + row.surplusHours, 0), 0);
  const recommendedPlanHours = hireDeficitHours;
  const recommendedPlanHeadcount = fullTimeHireCount;
  const expectedAfterRecommendedPlan = normalizeHourAnalysisNumber(projectedTotal.expected + recommendedPlanHours, 0);
  const wholeRolePlanHours = normalizeHourAnalysisNumber(hiringRecommendations.reduce((sum, row) => sum + row.hireHours, 0), 0);
  const wholeRolePlanHeadcount = hiringRecommendations.reduce((sum, row) => sum + row.hireCount, 0);
  const expectedAfterWholeRolePlan = normalizeHourAnalysisNumber(projectedTotal.expected + wholeRolePlanHours, 0);
  const headcountTotals = headcountRows.reduce((acc, row) => ({
    fullTime: acc.fullTime + row.fullTime,
    partTime: acc.partTime + row.partTime,
    unassigned: acc.unassigned + row.unassigned,
    total: acc.total + row.total,
    whatIfFullTime: acc.whatIfFullTime + row.whatIfFullTime,
    whatIfPartTime: acc.whatIfPartTime + row.whatIfPartTime,
    whatIfTotal: acc.whatIfTotal + row.whatIfTotal,
  }), { fullTime: 0, partTime: 0, unassigned: 0, total: 0, whatIfFullTime: 0, whatIfPartTime: 0, whatIfTotal: 0 });

  return {
    settings: normalizedSettings,
    rows: [...employeeRows, ...whatIfRows],
    employeeRows,
    whatIfRows,
    headcountRows,
    headcountTotals,
    weeklyRows,
    laborModelSummary,
    totals: {
      ...totals,
      rosterRange: totals.total,
      whatIfRange: totals.whatIfTotal,
      projectedFullTimeRange: projectedFullTime,
      projectedPartTimeRange: projectedPartTime,
      projectedRange: projectedTotal,
      projectedFullTime: projectedFullTime.expected,
      projectedPartTime: projectedPartTime.expected,
      projectedTotal: projectedTotal.expected,
      requiredDaily,
      requiredWeekly,
      targetWeekly,
      healthyLowWeekly: capacityStandard.healthyLowWeekly,
      healthyHighWeekly: capacityStandard.healthyHighWeekly,
      overRosteredWeekly: capacityStandard.overRosteredWeekly,
      capacityStandard,
      expectedGapToTarget,
      hireDeficitHours,
      fullTimeEquivalentHires,
      fullTimeHireCount,
      hiringRecommendations,
      roleDeficitHours,
      roleSurplusRows,
      roleSurplusHours,
      recommendedPlanHours,
      recommendedPlanHeadcount,
      expectedAfterRecommendedPlan,
      wholeRolePlanHours,
      wholeRolePlanHeadcount,
      expectedAfterWholeRolePlan,
      reservePercent: normalizedSettings.thresholds.reserve_percent,
      capacityStatus: buildHourAnalysisCapacityStatus({ requiredWeekly, targetWeekly, capacity: projectedTotal, standard: capacityStandard }),
      min: totals.total.min,
      expected: totals.total.expected,
      max: totals.total.max,
      whatIfMin: totals.whatIfTotal.min,
      whatIfExpected: totals.whatIfTotal.expected,
      whatIfMax: totals.whatIfTotal.max,
      projectedMin: projectedTotal.min,
      projectedExpected: projectedTotal.expected,
      projectedMax: projectedTotal.max,
      total: totals.total.expected,
      whatIfTotal: totals.whatIfTotal.expected,
      projectedHeadcount: headcountTotals.total + headcountTotals.whatIfTotal,
      projectedFullTimeHeadcount: headcountTotals.fullTime + headcountTotals.whatIfFullTime,
      projectedPartTimeHeadcount: headcountTotals.partTime + headcountTotals.whatIfPartTime,
    },
  };
}









// Branded checkbox for the Requirements applicability matrix (requirement × position). A styled
// button rather than a raw input: forest-green fill + check when on, a clear border when off, with a
// hover ring, press feedback, and a busy state while the toggle persists. Styles live in the
// Requirements view's scoped <style> block (.compliance-matrix-check).
function ComplianceMatrixCheckbox({ checked, disabled = false, busy = false, title, onToggle }) {
  const className = ["compliance-matrix-check", checked && "is-checked", busy && "is-busy"].filter(Boolean).join(" ");
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      aria-busy={busy || undefined}
      title={title}
      disabled={disabled}
      onClick={() => onToggle(!checked)}
      className={className}
    >
      {checked ? <I.Check /> : null}
    </button>
  );
}

// Creatable group combobox for the compliance requirement editor: type to filter existing groups,
// pick a suggestion, or create a brand-new group. Module-scoped so its open/active state survives
// parent re-renders. `value` is the visible label text; the caller resolves it to a display_group key.
function ComplianceGroupCombobox({ value, onChange, options = [] }) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const inputRef = useRef(null);
  const popoverRef = useRef(null);

  const query = String(value || "").trim().toLowerCase();
  const matches = (options || []).filter((option) => !query || option.label.toLowerCase().includes(query));
  const hasExact = (options || []).some((option) => option.label.toLowerCase() === query);
  const rows = [
    ...matches.map((option) => ({ type: "pick", label: option.label })),
    ...(query && !hasExact ? [{ type: "create", label: String(value).trim() }] : []),
  ];

  useEffect(() => {
    const handlePointerDown = (event) => {
      if (popoverRef.current?.contains(event.target) || inputRef.current?.contains(event.target)) return;
      setOpen(false);
      setActiveIndex(-1);
    };
    document.addEventListener("mousedown", handlePointerDown);
    return () => document.removeEventListener("mousedown", handlePointerDown);
  }, []);

  const choose = (row) => { onChange(row.label); setOpen(false); setActiveIndex(-1); };

  const handleKeyDown = (event) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      if (!open) { setOpen(true); return; }
      setActiveIndex((prev) => Math.min(prev + 1, rows.length - 1));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((prev) => Math.max(prev - 1, 0));
    } else if (event.key === "Enter" && open && activeIndex >= 0 && rows[activeIndex]) {
      event.preventDefault();
      choose(rows[activeIndex]);
    } else if (event.key === "Escape") {
      setOpen(false);
      setActiveIndex(-1);
    }
  };

  return (
    <div style={{ position: "relative" }}>
      <input
        ref={inputRef}
        value={value || ""}
        onChange={(event) => { onChange(event.target.value); setOpen(true); setActiveIndex(-1); }}
        onKeyDown={handleKeyDown}
        onFocus={() => setOpen(true)}
        placeholder="Type a group, e.g. Training, Onboarding…"
        autoComplete="off"
        style={{ width: "100%", boxSizing: "border-box", padding: "10px 14px", fontSize: 14, borderRadius: 10, border: `1.5px solid ${C.border}`, background: C.surface, color: C.text, fontFamily: "inherit", outline: "none" }}
      />
      {open && rows.length > 0 ? (
        <div
          ref={popoverRef}
          style={{ position: "absolute", top: "100%", left: 0, right: 0, zIndex: 100, marginTop: 4, background: C.surface, border: `1.5px solid ${C.border}`, borderRadius: 10, boxShadow: "0 12px 32px rgba(15, 23, 42, 0.16)", overflow: "hidden", maxHeight: 240, overflowY: "auto" }}
        >
          {rows.map((row, index) => (
            <button
              key={`${row.type}:${row.label}`}
              type="button"
              onMouseDown={(event) => { event.preventDefault(); choose(row); }}
              onMouseEnter={() => setActiveIndex(index)}
              style={{ display: "flex", width: "100%", alignItems: "center", gap: 8, border: "none", background: index === activeIndex ? C.surfaceHover : "transparent", color: C.text, fontFamily: "inherit", fontSize: 13, fontWeight: 700, textAlign: "left", padding: "9px 12px", cursor: "pointer" }}
            >
              {row.type === "create" ? (
                <>
                  <span style={{ color: C.pri, fontWeight: 900 }}>+</span>
                  <span>Create “{row.label}”</span>
                </>
              ) : (
                <span>{row.label}</span>
              )}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function compareCompliancePolicyRequirements(left = {}, right = {}) {
  const leftDefault = isDefaultReviewComplianceRequirement(left);
  const rightDefault = isDefaultReviewComplianceRequirement(right);
  if (leftDefault !== rightDefault) {
    return leftDefault ? -1 : 1; // 30/60/90 (defaults) always before custom columns
  }
  if (leftDefault && rightDefault) {
    const ld = getOffsetDaysForRequirement(left) ?? 9999;
    const rd = getOffsetDaysForRequirement(right) ?? 9999;
    if (ld !== rd) return ld - rd; // 30 then 60 then 90
    return normalizeComplianceRequirementLabel(left).localeCompare(normalizeComplianceRequirementLabel(right), undefined, { sensitivity: "base" });
  }
  // Custom requirements: user-controlled order via display_order (Requirements tab reorder),
  // then created_at (order added), then label.
  const lo = Number(left.display_order ?? left.displayOrder ?? (left.metadata && isObjectRow(left.metadata) ? left.metadata.display_order : null));
  const ro = Number(right.display_order ?? right.displayOrder ?? (right.metadata && isObjectRow(right.metadata) ? right.metadata.display_order : null));
  if (Number.isFinite(lo) && Number.isFinite(ro) && lo !== ro) return lo - ro;
  const lc = left.created_at || left.createdAt || (left.metadata && isObjectRow(left.metadata) ? left.metadata.created_at : "") || "";
  const rc = right.created_at || right.createdAt || (right.metadata && isObjectRow(right.metadata) ? right.metadata.created_at : "") || "";
  if (lc && rc) {
    const c = lc.localeCompare(rc);
    if (c !== 0) return c;
  }
  return normalizeComplianceRequirementLabel(left).localeCompare(normalizeComplianceRequirementLabel(right), undefined, { sensitivity: "base" });
}

function getDaysSince(dateValue) {
  if (!dateValue) return null;
  const start = new Date(`${dateValue}T12:00:00`);
  if (Number.isNaN(start.getTime())) return null;
  const today = new Date(`${todayStr()}T12:00:00`);
  return Math.floor((today.getTime() - start.getTime()) / (24 * 60 * 60 * 1000));
}


function getTrainingComplianceState(row) {
  const cprCompliant = ["current", "due_soon"].includes(String(row?.cpr_status || ""));
  const completedTraining = Number(row?.completed_training_record_count || 0) > 0
    || ["complete", "completed", "passed"].includes(String(row?.active_training_status || "").toLowerCase());
  const inTraining = Boolean(row?.active_training_record_id)
    || ["in_progress", "not_started"].includes(String(row?.active_training_status || "").toLowerCase());
  const daysSinceStart = getDaysSince(row?.start_date);
  const withinGraceWindow = daysSinceStart != null && daysSinceStart < TRAINING_GRACE_PERIOD_DAYS;

  if (completedTraining && cprCompliant) {
    return { label: "Compliant", color: "success", inProgress: false };
  }

  if (withinGraceWindow && (inTraining || !cprCompliant || !completedTraining)) {
    return { label: "In Progress", color: "warning", inProgress: true };
  }

  return { label: "Non-Compliant", color: "danger", inProgress: false };
}









function resolveLaborActorNameByUserId(value = "", employeeRows = []) {
  const userId = normalizeOptionalUuid(value);
  if (!userId) return "";
  const match = toObjectRows(employeeRows).find((employee) => (
    normalizeOptionalUuid(employee.linked_user_id) === userId
    || normalizeOptionalUuid(employee.user_id) === userId
    || normalizeOptionalUuid(employee.linked_lite_profile_user_id) === userId
  ));
  return String(match?.full_name || match?.name || "").trim();
}

function resolveLaborActorDisplayName(row = {}, employeeRows = []) {
  const userIdCandidates = [
    row.actor_user_id,
    row.created_by_user_id,
    row.updated_by_user_id,
    row.deleted_by_user_id,
    row.uploaded_by_user_id,
    row.reviewer_user_id,
  ];
  for (const candidate of userIdCandidates) {
    const actorName = resolveLaborActorNameByUserId(candidate, employeeRows);
    if (actorName) return actorName;
  }
  const candidates = [
    row.actor_email,
    row.actor_name,
    row.actorName,
    row.created_by_email,
    row.created_by_name,
    row.createdByName,
    row.updated_by_email,
    row.updated_by_name,
    row.updatedByName,
    row.email,
  ];
  for (const candidate of candidates) {
    const actorName = resolveLaborActorNameByEmail(candidate, employeeRows);
    if (actorName) return actorName;
  }
  return "";
}

function resolveReadinessCellEmailActorDisplayName(cell = {}, status = "", employeeRows = []) {
  const metadata = isObjectRow(cell?.metadata) ? cell.metadata : {};
  const normalizedStatus = normalizePctReadinessStatus(status || cell.readiness_status || cell.status);
  if (normalizedStatus === "not_started") return "";
  const statusCandidates = normalizedStatus === "verified" || normalizedStatus === "waived"
    ? [
        cell.verified_by,
        metadata.verified_by_name,
        metadata.verified_accuracy_by,
        metadata.verified_by,
        cell.completed_by_name,
        metadata.completed_by_name,
        metadata.last_updated_by_name,
        cell.evaluated_by_name,
      ]
    : [
        cell.demonstrated_by,
        metadata.demonstrated_by_name,
        metadata.demonstrated_by,
        metadata.last_updated_by_name,
        cell.evaluated_by_name,
        cell.completed_by_name,
        metadata.completed_by_name,
      ];
  const nestedCandidates = [
    isObjectRow(metadata.raw_values) ? metadata.raw_values : {},
    isObjectRow(metadata.source_values) ? metadata.source_values : {},
  ].flatMap((source) => normalizedStatus === "verified" || normalizedStatus === "waived"
    ? [source.verified_by_name, source.verified_accuracy_by, source.verified_by, source.completed_by_name]
    : [source.demonstrated_by_name, source.demonstrated_by, source.completed_by_name]);
  for (const candidate of [...statusCandidates, ...nestedCandidates]) {
    const actorName = resolveLaborActorNameByEmail(candidate, employeeRows);
    if (actorName) return actorName;
  }
  return "";
}









function getHistoryTimestampValue(value) {
  const time = value ? new Date(value).getTime() : NaN;
  return Number.isFinite(time) ? time : 0;
}







export function buildTrainingHistoryDayMetrics(rows = [], dateValue = "") {
  const normalizedRows = toObjectRows(rows);
  const targetDate = String(dateValue || "").trim() || getTrainingHistoryRowDate(normalizedRows[0]) || todayStr();
  const dayRows = normalizedRows.filter((row) => getTrainingHistoryRowDate(row) === targetDate);
  return {
    date: targetDate,
    activityCount: dayRows.length,
    employeeCount: new Set(dayRows.map((row) => String(row.employeeName || "").trim()).filter(Boolean)).size,
  };
}











function buildComplianceHistoryDetailParts({ event = {}, reviewInstance = {}, checkpointLabel = "" } = {}) {
  const previousState = readComplianceHistoryState(event, "old");
  const nextState = readComplianceHistoryState(event, "new");
  const eventMetadata = readComplianceHistoryMetadata(event);
  const instanceMetadata = readComplianceHistoryMetadata(reviewInstance);
  const completionEvidence = readComplianceHistoryMetadata(nextState).completion_evidence
    || eventMetadata.completion_evidence
    || instanceMetadata.completion_evidence
    || {};
  const completionWaiver = readComplianceHistoryMetadata(nextState).completion_waiver
    || eventMetadata.completion_waiver
    || instanceMetadata.completion_waiver
    || {};
  const dueDate = nextState.due_date || previousState.due_date || reviewInstance.due_date || eventMetadata.due_date;
  const completedDate = nextState.completed_at || reviewInstance.completed_at || completionEvidence.completed_on || completionWaiver.completed_on;
  const reviewItemLabel = eventMetadata.review_item_label || "";
  const parts = [
    dueDate ? `Due ${formatLaborDate(dueDate)}` : "",
    completedDate ? `Action ${formatLaborDate(completedDate)}` : "",
    reviewItemLabel && reviewItemLabel !== checkpointLabel ? reviewItemLabel : "",
    completionEvidence.file_name ? `Evidence ${completionEvidence.file_name}` : "",
    completionWaiver.reason ? `Waiver ${completionWaiver.reason}` : "",
  ].filter(Boolean);
  return parts;
}


export function buildComplianceHistoryRows({
  events = [],
  reviewInstances = [],
  reviewCycles = [],
  requirements = [],
  laborEmployeeMap = {},
} = {}) {
  const reviewInstanceMap = Object.fromEntries(
    toObjectRows(reviewInstances)
      .map((instance) => [String(instance.id || ""), instance])
      .filter(([id]) => id)
  );

  return toObjectRows(events)
    .filter(isComplianceHistoryEvent)
    .map((event, index) => {
      const reviewInstance = findComplianceHistoryReviewInstance(event, reviewInstanceMap) || {};
      const previousState = readComplianceHistoryState(event, "old");
      const nextState = readComplianceHistoryState(event, "new");
      const metadata = readComplianceHistoryMetadata(event);
      const reviewCycle = metadata.review_cycle
        || nextState.review_cycle
        || previousState.review_cycle
        || reviewInstance.review_cycle
        || event.summary
        || "";
      const cycle = findComplianceHistoryCycle(reviewCycle, reviewCycles);
      const requirement = findComplianceHistoryRequirement(
        reviewCycle,
        metadata.requirement_id || nextState.requirement_id || previousState.requirement_id,
        requirements,
      );
      const fallbackCycleLabel = normalizeComplianceHistoryCycleLabel(reviewCycle);
      const checkpointLabel = cycle?.label
        || (requirement ? normalizeComplianceRequirementLabel(requirement) : "")
        || fallbackCycleLabel
        || normalizeComplianceHistoryCycleLabel(event.summary)
        || "Compliance checkpoint";
      const employeeId = event.labor_employee_id || reviewInstance.labor_employee_id || "";
      const employee = laborEmployeeMap[employeeId] || {};
      const detailParts = buildComplianceHistoryDetailParts({ event, reviewInstance, checkpointLabel });
      return {
        ...event,
        id: `compliance_event_${event.id || `${event.created_at || event.occurred_at || "event"}_${index}`}`,
        entityId: event.id,
        historyKind: "compliance_event",
        created_at: event.occurred_at || event.created_at || reviewInstance.updated_at || reviewInstance.created_at,
        labor_employee_id: employeeId,
        reviewInstance,
        cycle,
        requirement,
        categoryTaskLabel: [
          checkpointLabel,
          metadata.review_item_label,
        ].filter(Boolean).join(" / "),
        employeeName: employee.full_name || nextState.employee_full_name || previousState.employee_full_name || reviewInstance.employee_full_name || "Unknown employee",
        actionLabel: normalizeComplianceHistoryActionLabel(event.title || event.event_type || "Compliance update"),
        actorDisplayName: getComplianceHistoryActor(event, reviewInstance),
        statusChange: getComplianceHistoryStatusChange(event),
        summary: checkpointLabel,
        detailParts,
      };
    })
    .sort((a, b) => getHistoryTimestampValue(b.created_at) - getHistoryTimestampValue(a.created_at));
}







function buildComplianceAuditDetailParts(event = {}) {
  const before = readComplianceAuditSnapshot(event, "before_snapshot");
  const after = readComplianceAuditSnapshot(event, "after_snapshot");
  const snapshot = Object.keys(after).length > 0 ? after : before;
  const metadata = readComplianceHistoryMetadata(snapshot);
  return [
    snapshot.due_date ? `Due ${formatLaborDate(snapshot.due_date)}` : "",
    snapshot.completed_on ? `Action ${formatLaborDate(snapshot.completed_on)}` : "",
    snapshot.evidence_label ? `Evidence ${snapshot.evidence_label}` : "",
    snapshot.source_note ? String(snapshot.source_note) : "",
    metadata.completion_mode ? `State ${getComplianceStateLabel(metadata.completion_mode)}` : "",
  ].filter(Boolean);
}

function buildComplianceCellHistoryRows({
  laborEmployeeId = "",
  requirementId = "",
  reviewInstanceId = "",
  reviewCycle = {},
  auditEvents = [],
  complianceNotes = [],
  employeeHistoryEvents = [],
  documents = [],
} = {}) {
  const employeeId = normalizeOptionalUuid(laborEmployeeId);
  const targetRequirementId = normalizeOptionalUuid(requirementId);
  const targetReviewInstanceId = normalizeOptionalUuid(reviewInstanceId);
  const evidence = getCompletionEvidence(reviewCycle);
  const documentIds = new Set([
    evidence.documentId,
    evidence.id,
    getReviewCyclePolicyCell(reviewCycle).labor_employee_document_id,
  ].map((value) => normalizeOptionalUuid(value)).filter(Boolean));

  const auditRows = toObjectRows(auditEvents)
    .filter((event) => String(event.table_name || "") !== "labor_compliance_notes")
    .filter((event) => getComplianceAuditEmployeeId(event) === employeeId)
    .filter((event) => !targetRequirementId || getComplianceAuditRequirementId(event) === targetRequirementId)
    .map((event) => {
      const before = readComplianceAuditSnapshot(event, "before_snapshot");
      const after = readComplianceAuditSnapshot(event, "after_snapshot");
      const snapshot = Object.keys(after).length > 0 ? after : before;
      if (snapshot.labor_employee_document_id) documentIds.add(normalizeOptionalUuid(snapshot.labor_employee_document_id));
      return {
        id: `audit_${event.id}`,
        kind: "audit",
        created_at: event.created_at,
        actionLabel: getComplianceAuditActionLabel(event),
        actorDisplayName: resolveVerifiedActorDisplayName({
          actor_full_name: event.actor_full_name,
          actor_name: event.actor_name,
          actor_user_id: event.actor_user_id,
        }) || "Staff",
        detailParts: buildComplianceAuditDetailParts(event),
      };
    });

  const noteRows = toObjectRows(complianceNotes)
    .filter((note) => normalizeOptionalUuid(note.labor_employee_id) === employeeId)
    .filter((note) => !targetRequirementId || normalizeOptionalUuid(note.requirement_id) === targetRequirementId)
    .map((note) => ({
      id: `note_${note.id}`,
      kind: "note",
      created_at: note.created_at,
      actionLabel: "Note Added",
      actorDisplayName: resolveVerifiedActorDisplayName({
        created_by_full_name: note.created_by_full_name,
        created_by_name: note.created_by_name,
        created_by_user_id: note.created_by_user_id,
      }) || "Staff",
      detailParts: [note.note_text].filter(Boolean),
    }));

  const reviewRows = toObjectRows(employeeHistoryEvents)
    .filter((event) => normalizeOptionalUuid(event.labor_employee_id) === employeeId)
    .filter((event) => !targetReviewInstanceId || normalizeOptionalUuid(event.source_id) === targetReviewInstanceId)
    .filter((event) => String(event.source_table || "") === "employee_review_instances" || String(event.source_table || "") === "employee_review_responses")
    .map((event) => ({
      id: `history_${event.id}`,
      kind: "review",
      created_at: event.occurred_at || event.created_at,
      actionLabel: normalizeComplianceHistoryActionLabel(event.title || event.event_type || "Review Activity"),
      actorDisplayName: getComplianceHistoryActor(event),
      detailParts: buildComplianceHistoryDetailParts({ event, reviewInstance: {}, checkpointLabel: "" }),
    }));

  const documentRows = toObjectRows(documents)
    .filter((document) => normalizeOptionalUuid(document.labor_employee_id) === employeeId)
    .filter((document) => documentIds.has(normalizeOptionalUuid(document.id)))
    .map((document) => ({
      id: `document_${document.id}`,
      kind: "document",
      created_at: document.uploaded_at,
      actionLabel: "PDF Uploaded",
      actorDisplayName: document.uploaded_by_name || "Staff",
      detailParts: [
        document.file_name || "Compliance evidence PDF",
        document.file_size_bytes ? formatLaborAttachmentFileSize(document.file_size_bytes) : "",
      ].filter(Boolean),
    }));

  const seen = new Set();
  return [...auditRows, ...noteRows, ...reviewRows, ...documentRows]
    .filter((row) => {
      const key = `${row.kind}:${row.created_at}:${row.actionLabel}:${row.detailParts.join("|")}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => getHistoryTimestampValue(b.created_at) - getHistoryTimestampValue(a.created_at));
}

export function applyLaborRosterFilters(rows, filters) {
  const keys = Object.keys(filters || {});
  if (keys.length === 0) return rows;
  const today = todayStr();
  const needsValue = (op) => !["empty", "notEmpty", "has", "missing", "overdue", "today", "thisWeek", "hasDate", "noDate"].includes(op);
  const parseDate = (value) => {
    const text = String(value || "");
    if (!text) return "";
    return text.includes("T") ? text.split("T")[0] : text;
  };
  const matchText = (source, op, value, { digitsOnly = false } = {}) => {
    const left = digitsOnly ? String(source || "").replace(/\D/g, "") : String(source || "").toLowerCase();
    const right = digitsOnly ? String(value || "").replace(/\D/g, "") : String(value || "").toLowerCase();
    if (op === "contains") return left.includes(right);
    if (op === "equals") return left === right;
    if (op === "starts") return left.startsWith(right);
    if (op === "empty") return !left;
    if (op === "notEmpty") return !!left;
    return true;
  };

  return rows.filter((row) => keys.every((key) => {
    const filter = filters[key];
    if (!filter) return true;
    const op = filter.op;
    const val = filter.val;
    if (needsValue(op) && val === "") return true;

    if (key === "first_name") return matchText(row.first_name, op, val);
    if (key === "last_name") return matchText(row.last_name, op, val);
    if (key === "email") return matchText(row.contact_email, op, val);
    if (key === "phone") return matchText(row.contact_phone, op, val, { digitsOnly: true });
    if (key === "position") return matchText(row.position_title, op, val);
    if (key === "commitment") {
      const label = getLaborEmploymentCommitmentLabel(row.employment_commitment);
      if (op === "is") return label === val;
      if (op === "isNot") return label !== val;
      return true;
    }
    if (key === "employment_status") {
      const explicitStatus = String(row.employment_status || "").toLowerCase();
      const status = explicitStatus || (row.is_active === false ? "inactive" : "active");
      if (val === "all") return true;
      if (op === "is") return status === val;
      if (op === "isNot") return status !== val;
      return true;
    }
    if (key === "training") {
      const status = String(row.training_compliance?.label || "");
      if (op === "is") return status === val;
      if (op === "isNot") return status !== val;
      return true;
    }
    if (key === "performance_reviews") {
      const status = String(row.performance_review_compliance?.label || "");
      if (op === "is") return status === val;
      if (op === "isNot") return status !== val;
      return true;
    }

    const dateValue = (() => {
      if (key === "start_date") return parseDate(row.start_date);
      if (String(key || "").startsWith(REVIEW_CYCLE_SORT_KEY_PREFIX)) return parseDate(getReviewCycleDueDateForSort(row, key));
      return "";
    })();

    if (key === "start_date" || String(key || "").startsWith(REVIEW_CYCLE_SORT_KEY_PREFIX)) {
      if (op === "hasDate") return !!dateValue;
      if (op === "noDate") return !dateValue;
      if (!dateValue) return false;
      if (op === "after") return dateValue > val;
      if (op === "before") return dateValue < val;
      if (op === "inLastDays") {
        const diff = Math.floor((new Date(`${today}T12:00:00`) - new Date(`${dateValue}T12:00:00`)) / 86400000);
        return diff <= parseInt(val, 10);
      }
    }

    return true;
  }));
}

