        model: { ...normalizedModel, days: { ...normalizedModel.days, [normalizedDay]: { ...day, columns: nextColumns, rows: nextRows } } },
        changedKeys: ["capacity", "labor-model", `labor-model:${normalizedDay}`, `labor-model-column:${nextColumn.id}`],
